# Find room (IfcSpace) by GlobalId and return its area in m^2
# Prefer explicit quantities (Qto_SpaceBaseQuantities.GrossFloorArea/NetFloorArea)
# Fallback: compute from IfcSpace boundaries/footprint only if needed (not using geom).

target_gid = '2UsXAbj6n0fwEWqdkVuHyo'

space = None
for ent in ifc.by_type('IfcSpace'):
    if getattr(ent, 'GlobalId', None) == target_gid:
        space = ent
        break

out = {
    'global_id': target_gid,
    'found': space is not None,
    'name': getattr(space, 'Name', None) if space else None,
    'long_name': getattr(space, 'LongName', None) if space else None,
    'area_m2': None,
    'area_source': None,
}

if space is None:
    result = out

else:
    def area_from_element_quantity(elem):
        # Look into IsDefinedBy -> IfcRelDefinesByProperties -> IfcElementQuantity
        for rel in getattr(elem, 'IsDefinedBy', []) or []:
            if not rel.is_a('IfcRelDefinesByProperties'):
                continue
            pset = rel.RelatingPropertyDefinition
            if not pset:
                continue
            if pset.is_a('IfcElementQuantity'):
                # Search quantities
                for q in pset.Quantities or []:
                    if not q:
                        continue
                    # Common names for floor area in Qto_SpaceBaseQuantities
                    if q.is_a('IfcQuantityArea') and (q.Name in ('GrossFloorArea','NetFloorArea','FloorArea','Area')):
                        val = q.AreaValue
                        if val is not None:
                            return float(val), f"{pset.Name}.{q.Name}"
        return None, None

    area, src = area_from_element_quantity(space)

    # Also check IfcRelDefinesByProperties -> IfcPropertySet with IfcPropertySingleValue Area
    if area is None:
        for rel in getattr(space, 'IsDefinedBy', []) or []:
            if not rel.is_a('IfcRelDefinesByProperties'):
                continue
            pset = rel.RelatingPropertyDefinition
            if not pset or not pset.is_a('IfcPropertySet'):
                continue
            for prop in pset.HasProperties or []:
                if not prop or not prop.is_a('IfcPropertySingleValue'):
                    continue
                if prop.Name in ('Area','GrossFloorArea','NetFloorArea','FloorArea'):
                    nv = prop.NominalValue
                    if nv is None:
                        continue
                    try:
                        area = float(nv.wrappedValue)
                        src = f"{pset.Name}.{prop.Name}"
                        break
                    except Exception:
                        pass
            if area is not None:
                break

    # If still none, attempt to use IfcSpace.Area (rare / not standard)
    if area is None and hasattr(space, 'Area'):
        try:
            area = float(space.Area)
            src = 'IfcSpace.Area'
        except Exception:
            pass

    out['area_m2'] = area
    out['area_source'] = src
    result = out

