# Fallback: compute area from 2D footprint in IfcSpace.Representation (SweptSolid/Curve2D)
# Avoid ifcopenshell.geom. Handle IfcArbitraryClosedProfileDef with IfcPolyline/IfcIndexedPolyCurve.

import math

target_gid = '2UsXAbj6n0fwEWqdkVuHyo'

def get_units_scale_to_m(ifc):
    # Returns length unit scale to meters
    proj = ifc.by_type('IfcProject')[0]
    ua = proj.UnitsInContext
    if not ua:
        return 1.0
    # look for IfcSIUnit LENGTHUNIT
    for u in ua.Units or []:
        if u.is_a('IfcSIUnit') and u.UnitType == 'LENGTHUNIT':
            name = u.Name  # METRE, MILLIMETRE, etc.
            prefix = getattr(u, 'Prefix', None)
            scale = 1.0
            if name == 'METRE':
                scale = 1.0
            # prefix handling
            if prefix == 'MILLI':
                scale *= 0.001
            elif prefix == 'CENTI':
                scale *= 0.01
            elif prefix == 'DECI':
                scale *= 0.1
            elif prefix == 'KILO':
                scale *= 1000.0
            return scale
    # IfcConversionBasedUnit
    for u in ua.Units or []:
        if u.is_a('IfcConversionBasedUnit') and u.UnitType == 'LENGTHUNIT':
            # ConversionFactor: IfcMeasureWithUnit(ValueComponent, UnitComponent)
            mf = u.ConversionFactor
            try:
                val = float(mf.ValueComponent.wrappedValue)
            except Exception:
                val = None
            # recurse on unitcomponent
            unitcomp = mf.UnitComponent
            base = 1.0
            if unitcomp and unitcomp.is_a('IfcSIUnit'):
                base = 1.0
                prefix = getattr(unitcomp, 'Prefix', None)
                if prefix == 'MILLI':
                    base *= 0.001
                elif prefix == 'CENTI':
                    base *= 0.01
                elif prefix == 'DECI':
                    base *= 0.1
                elif prefix == 'KILO':
                    base *= 1000.0
            if val is not None:
                return val * base
    return 1.0

scale = get_units_scale_to_m(ifc)

space = None
for ent in ifc.by_type('IfcSpace'):
    if ent.GlobalId == target_gid:
        space = ent
        break

out = {'global_id': target_gid, 'found': space is not None, 'area_m2': None, 'area_source': None}

if space is None:
    result = out
else:
    def poly_area(coords):
        # coords: list of (x,y); may be closed or not
        if len(coords) < 3:
            return 0.0
        pts = coords[:]
        if pts[0] != pts[-1]:
            pts.append(pts[0])
        a = 0.0
        for i in range(len(pts)-1):
            x1,y1 = pts[i]
            x2,y2 = pts[i+1]
            a += x1*y2 - x2*y1
        return abs(a) * 0.5

    def coords_from_curve(curve):
        # Return list of (x,y) in model units
        if curve.is_a('IfcPolyline'):
            coords = []
            for p in curve.Points:
                c = p.Coordinates
                coords.append((float(c[0]), float(c[1])))
            return coords
        if curve.is_a('IfcIndexedPolyCurve'):
            pl = curve.Points  # IfcCartesianPointList2D/3D
            coord_list = pl.CoordList
            coords = []
            # Segments may reference indices; if absent, take all points
            if curve.Segments:
                for seg in curve.Segments:
                    if seg.is_a('IfcLineIndex'):
                        for idx in seg.wrappedValue:
                            x,y = coord_list[idx-1][0], coord_list[idx-1][1]
                            coords.append((float(x), float(y)))
                    elif seg.is_a('IfcArcIndex'):
                        # arcs: approximate by just using end points (fallback)
                        idxs = seg.wrappedValue
                        for idx in idxs:
                            x,y = coord_list[idx-1][0], coord_list[idx-1][1]
                            coords.append((float(x), float(y)))
            else:
                for xy in coord_list:
                    coords.append((float(xy[0]), float(xy[1])))
            return coords
        return None

    def area_from_representation(sp):
        rep = sp.Representation
        if not rep:
            return None, None
        for r in rep.Representations or []:
            # look for footprint-like or swept solid profile
            for item in r.Items or []:
                if item.is_a('IfcExtrudedAreaSolid'):
                    prof = item.SweptArea
                    if prof and prof.is_a('IfcArbitraryClosedProfileDef'):
                        curve = prof.OuterCurve
                        coords = coords_from_curve(curve) if curve else None
                        if coords:
                            return poly_area(coords) * (scale**2), 'IfcExtrudedAreaSolid.SweptArea'
                if item.is_a('IfcArbitraryClosedProfileDef'):
                    curve = item.OuterCurve
                    coords = coords_from_curve(curve) if curve else None
                    if coords:
                        return poly_area(coords) * (scale**2), 'IfcArbitraryClosedProfileDef'
                # Some models store footprint as IfcShapeRepresentation with IfcPolyline directly
                if item.is_a('IfcPolyline'):
                    coords = coords_from_curve(item)
                    if coords:
                        return poly_area(coords) * (scale**2), 'IfcPolyline'
        return None, None

    area, src = area_from_representation(space)
    out['area_m2'] = area
    out['area_source'] = src
    result = out

