# Extract area by reading the profile of the IfcExtrudedAreaSolid in Body representation.
# Handle IfcRectangleProfileDef / IfcArbitraryClosedProfileDef.

import math

target_gid = '2UsXAbj6n0fwEWqdkVuHyo'

space = next((s for s in ifc.by_type('IfcSpace') if s.GlobalId == target_gid), None)

def get_units_scale_to_m(ifc):
    proj = ifc.by_type('IfcProject')[0]
    ua = proj.UnitsInContext
    if not ua:
        return 1.0
    for u in ua.Units or []:
        if u.is_a('IfcSIUnit') and u.UnitType == 'LENGTHUNIT':
            name = u.Name
            prefix = getattr(u, 'Prefix', None)
            scale = 1.0 if name == 'METRE' else 1.0
            if prefix == 'MILLI': scale *= 0.001
            elif prefix == 'CENTI': scale *= 0.01
            elif prefix == 'DECI': scale *= 0.1
            elif prefix == 'KILO': scale *= 1000.0
            return scale
    return 1.0

scale = get_units_scale_to_m(ifc)

result = {'global_id': target_gid, 'found': space is not None, 'area_m2': None, 'area_source': None}

if space and space.Representation:
    def poly_area(coords):
        if len(coords) < 3:
            return 0.0
        pts = coords[:]
        if pts[0] != pts[-1]:
            pts.append(pts[0])
        a = 0.0
        for i in range(len(pts)-1):
            x1,y1 = pts[i]
            x2,y2 = pts[i+1]
            a += x1*y2 - x2*y1
        return abs(a) * 0.5

    def coords_from_curve(curve):
        if curve.is_a('IfcPolyline'):
            return [(float(p.Coordinates[0]), float(p.Coordinates[1])) for p in curve.Points]
        if curve.is_a('IfcIndexedPolyCurve'):
            pl = curve.Points
            cl = pl.CoordList
            coords = []
            if curve.Segments:
                for seg in curve.Segments:
                    idxs = seg.wrappedValue
                    for idx in idxs:
                        coords.append((float(cl[idx-1][0]), float(cl[idx-1][1])))
            else:
                coords = [(float(xy[0]), float(xy[1])) for xy in cl]
            return coords
        return None

    for shp in space.Representation.Representations or []:
        for item in shp.Items or []:
            if item.is_a('IfcExtrudedAreaSolid'):
                prof = item.SweptArea
                if prof.is_a('IfcRectangleProfileDef'):
                    x = float(prof.XDim)
                    y = float(prof.YDim)
                    area = x * y * (scale**2)
                    result['area_m2'] = area
                    result['area_source'] = 'IfcRectangleProfileDef (SweptArea of IfcExtrudedAreaSolid)'
                    break
                if prof.is_a('IfcArbitraryClosedProfileDef'):
                    curve = prof.OuterCurve
                    coords = coords_from_curve(curve) if curve else None
                    if coords:
                        area = poly_area(coords) * (scale**2)
                        result['area_m2'] = area
                        result['area_source'] = f'{curve.is_a()} (OuterCurve of IfcArbitraryClosedProfileDef)'
                        break
        if result['area_m2'] is not None:
            break

# Take off wall length (m) for GlobalId
# Avoid ifcopenshell.geom; use IfcQuantityLength if present, else derive from axis/body bounding box.

def _get_psets(el):
    try:
        import ifcopenshell.util.element as uel
        return uel.get_psets(el) or {}
    except Exception:
        return {}


def _length_from_qtos(el):
    # Search in element quantities for a length quantity
    qsets = {}
    try:
        import ifcopenshell.util.element as uel
        qsets = uel.get_psets(el, qtos_only=True) or {}
    except Exception:
        qsets = {}

    # Common names/keys
    cand_qsets = [
        "Qto_WallBaseQuantities",
        "BaseQuantities",
        "Qto_WallStandardCaseBaseQuantities",
    ]
    cand_keys = [
        "Length",
        "NetLength",
        "GrossLength",
        "OverallLength",
    ]
    for qs_name in cand_qsets + list(qsets.keys()):
        qs = qsets.get(qs_name)
        if not isinstance(qs, dict):
            continue
        for k in cand_keys + list(qs.keys()):
            v = qs.get(k)
            if isinstance(v, (int, float)):
                if v > 0:
                    return float(v), f"QTO:{qs_name}.{k}"
    return None, None


def _verts_from_representation(el):
    # Extract vertices from IfcFacetedBrep / IfcExtrudedAreaSolid (rect/circle) without geom engine.
    verts = []
    reps = []
    if getattr(el, "Representation", None) and el.Representation.Representations:
        reps = list(el.Representation.Representations)

    def add_point(p):
        if p is None:
            return
        try:
            coords = list(p.Coordinates)
            if len(coords) >= 3:
                verts.append((float(coords[0]), float(coords[1]), float(coords[2])))
        except Exception:
            pass

    def walk(item):
        if item is None:
            return
        t = item.is_a()
        if t == "IfcMappedItem":
            # Recurse into source representation
            walk(item.MappingSource.MappedRepresentation)
        elif t in ("IfcShapeRepresentation", "IfcTopologyRepresentation"):
            for it in item.Items:
                walk(it)
        elif t == "IfcFacetedBrep":
            shell = item.Outer
            for face in shell.CfsFaces:
                for bound in face.Bounds:
                    loop = bound.Bound
                    if loop.is_a("IfcPolyLoop"):
                        for cp in loop.Polygon:
                            add_point(cp)
        elif t == "IfcExtrudedAreaSolid":
            # Sample profile corners in local coords, then ignore placements (we only need extents)
            prof = item.SweptArea
            if prof.is_a("IfcRectangleProfileDef"):
                x = float(prof.XDim) / 2.0
                y = float(prof.YDim) / 2.0
                # local z will be 0..Depth
                d = float(item.Depth)
                for z in (0.0, d):
                    verts.extend([(x, y, z), (x, -y, z), (-x, y, z), (-x, -y, z)])
            elif prof.is_a("IfcCircleProfileDef"):
                r = float(prof.Radius)
                d = float(item.Depth)
                # approximate with 4 points
                for z in (0.0, d):
                    verts.extend([(r, 0.0, z), (-r, 0.0, z), (0.0, r, z), (0.0, -r, z)])
        elif t == "IfcBooleanClippingResult" or t == "IfcBooleanResult":
            walk(item.FirstOperand)
            walk(item.SecondOperand)
        elif t == "IfcSweptAreaSolid":
            # generic swept; try as extruded
            if hasattr(item, "Depth") and hasattr(item, "SweptArea"):
                walk(item)
        elif hasattr(item, "Items"):
            for it in item.Items:
                walk(it)

    for rep in reps:
        walk(rep)

    return verts


def _axis_polyline_length(el):
    # Compute length from Axis representation polyline if present
    if not getattr(el, "Representation", None):
        return None
    for rep in el.Representation.Representations or []:
        if rep.RepresentationIdentifier and rep.RepresentationIdentifier.lower() == "axis":
            for item in rep.Items:
                if item.is_a("IfcPolyline"):
                    pts = [(float(p.Coordinates[0]), float(p.Coordinates[1]), float(p.Coordinates[2]) if len(p.Coordinates) > 2 else 0.0)
                           for p in item.Points]
                    if len(pts) >= 2:
                        import math
                        L = 0.0
                        for a, b in zip(pts[:-1], pts[1:]):
                            dx, dy, dz = b[0]-a[0], b[1]-a[1], b[2]-a[2]
                            L += math.sqrt(dx*dx + dy*dy + dz*dz)
                        if L > 0:
                            return L
    return None


def _bbox_length_from_verts(verts):
    if not verts:
        return None
    xs = [v[0] for v in verts]
    ys = [v[1] for v in verts]
    zs = [v[2] for v in verts]
    dx = max(xs) - min(xs)
    dy = max(ys) - min(ys)
    dz = max(zs) - min(zs)
    # For a wall, length is typically the largest horizontal extent
    horiz = sorted([dx, dy], reverse=True)
    return horiz[0] if horiz[0] > 0 else None


gid = "22hyxvAPr65PFt9WZfHSKC"
el = ifc.by_guid(gid)
if el is None:
    result = {"error": f"No element found with GlobalId {gid}"}
else:
    # 1) Prefer QTO
    L, src = _length_from_qtos(el)
    # 2) Axis polyline
    if not L:
        axL = _axis_polyline_length(el)
        if axL:
            L, src = axL, "AXIS:IfcPolyline"
    # 3) fallback: representation extents
    if not L:
        verts = _verts_from_representation(el)
        bbL = _bbox_length_from_verts(verts)
        if bbL:
            L, src = bbL, "REP:BBOX(from explicit verts)"

    result = {
        "GlobalId": gid,
        "ifc_class": el.is_a(),
        "name": getattr(el, "Name", None),
        "length_m": float(L) if L else None,
        "source": src,
    }

