# Compute volume of room (IfcSpace) by GlobalId.
# Avoid ifcopenshell.geom unless necessary.

import ifcopenshell

gid = '2UsXAbj6n0fwEWqdkVuHyo'
space = ifc.by_guid(gid)

vol = None
source = None

if space is None:
    result = {'error': f'No entity with GlobalId {gid} found.'}
else:
    # 1) Try IfcElementQuantity / Qto_SpaceBaseQuantities (NetVolume/GrossVolume)
    def iter_rel_defines(elem):
        for rel in getattr(elem, 'IsDefinedBy', []) or []:
            yield rel

    def get_volume_from_quantities(elem):
        best = None
        best_name = None
        for rel in iter_rel_defines(elem):
            if not rel or not rel.is_a('IfcRelDefinesByProperties'):
                continue
            pdef = rel.RelatingPropertyDefinition
            if not pdef:
                continue
            # Can be IfcPropertySet or IfcElementQuantity
            if pdef.is_a('IfcElementQuantity'):
                qset_name = (pdef.Name or '').lower()
                for q in pdef.Quantities or []:
                    if not q or not q.is_a('IfcQuantityVolume'):
                        continue
                    qname = (q.Name or '').lower()
                    if q.VolumeValue is None:
                        continue
                    # Prefer netvolume then grossvolume then any volume
                    score = 0
                    if 'netvolume' in qname:
                        score = 3
                    elif 'grossvolume' in qname:
                        score = 2
                    elif 'volume' in qname:
                        score = 1
                    if best is None or score > best[0]:
                        best = (score, float(q.VolumeValue))
                        best_name = q.Name
            elif pdef.is_a('IfcPropertySet'):
                # sometimes volume stored as property
                for prop in pdef.HasProperties or []:
                    if not prop or not prop.is_a('IfcPropertySingleValue'):
                        continue
                    pname = (prop.Name or '').lower()
                    if 'volume' not in pname:
                        continue
                    nv = getattr(prop.NominalValue, 'wrappedValue', None) if prop.NominalValue else None
                    if nv is None:
                        continue
                    # treat as candidate
                    val = float(nv)
                    score = 1
                    if 'net' in pname:
                        score = 3
                    elif 'gross' in pname:
                        score = 2
                    if best is None or score > best[0]:
                        best = (score, val)
                        best_name = prop.Name
        if best:
            return best[1], best_name
        return None, None

    vol, name = get_volume_from_quantities(space)
    if vol is not None:
        source = f'Quantity/Property ({name})'

    # 2) Try base quantities via IfcRelDefinesByProperties referring to IfcElementQuantity inside Qto... (already covered)

    # 3) If not found, attempt compute from IfcSpace geometry (as last resort)
    if vol is None:
        try:
            import ifcopenshell.geom
            settings = ifcopenshell.geom.settings()
            settings.set(settings.USE_WORLD_COORDS, True)
            shape = ifcopenshell.geom.create_shape(settings, space)
            # shape.geometry is a triangulated mesh; compute volume from triangles.
            # geometry.verts is flat list [x,y,z,...], geometry.faces is indices.
            verts = shape.geometry.verts
            faces = shape.geometry.faces
            # Compute signed volume of closed mesh using tetrahedra w.r.t origin.
            v = 0.0
            # faces are triplets of indices
            for i in range(0, len(faces), 3):
                ia, ib, ic = faces[i], faces[i+1], faces[i+2]
                ax, ay, az = verts[3*ia], verts[3*ia+1], verts[3*ia+2]
                bx, by, bz = verts[3*ib], verts[3*ib+1], verts[3*ib+2]
                cx, cy, cz = verts[3*ic], verts[3*ic+1], verts[3*ic+2]
                # scalar triple product a.(bxc)/6
                v += (ax * (by*cz - bz*cy) + ay * (bz*cx - bx*cz) + az * (bx*cy - by*cx))
            vol = abs(v) / 6.0
            source = 'Computed from triangulated geometry'
        except Exception as e:
            result = {'error': f'Could not determine volume from quantities; geometry computation failed: {e}',
                      'entity': space.is_a(), 'name': getattr(space, 'Name', None)}

    if vol is not None:
        result = {'global_id': gid, 'entity': space.is_a(), 'name': getattr(space, 'Name', None), 'volume_m3': vol, 'source': source}

