import ifcopenshell

# Find wall with length ~ 5m from quantities
walls = ifc.by_type('IfcWall') + ifc.by_type('IfcWallStandardCase')

candidates = []

def get_length_from_element_quantities(elem):
    # Traverse IsDefinedBy -> IfcRelDefinesByProperties -> IfcElementQuantity
    for rel in getattr(elem, 'IsDefinedBy', []) or []:
        if not rel or not rel.is_a('IfcRelDefinesByProperties'):
            continue
        prop_def = rel.RelatingPropertyDefinition
        if not prop_def:
            continue
        if prop_def.is_a('IfcElementQuantity'):
            for q in prop_def.Quantities or []:
                # Common names: Length, NetLength, GrossLength
                if q.is_a('IfcQuantityLength'):
                    name = (q.Name or '').lower()
                    if 'length' in name or name in ('length', 'netlength', 'grosslength'):
                        val = q.LengthValue
                        if val is not None:
                            return float(val)
    return None

for w in walls:
    L = get_length_from_element_quantities(w)
    if L is None:
        continue
    candidates.append((w, L))

# pick those near 5.0m within tolerance
matches = [(w, L) for (w, L) in candidates if abs(L - 5.0) <= 1e-3]

result = None
if matches:
    # if multiple, return all ids; but user asked for the wall -> choose first and also include list
    result = {
