def length_scale_to_m():
    # IFC default is meters if no assignment; handle IfcSIUnit with prefix (MILLI) and IfcConversionBasedUnit
    for u in units:
        if not u:
            continue
        if u.is_a('IfcSIUnit') and u.UnitType == 'LENGTHUNIT':
            # Name could be METRE
            prefix = getattr(u, 'Prefix', None)
            # if Prefix is None -> meters
            if prefix is None:
                return 1.0
            # handle common
            if str(prefix).upper() == 'MILLI':
                return 0.001
            if str(prefix).upper() == 'CENTI':
                return 0.01
            if str(prefix).upper() == 'DECI':
                return 0.1
            if str(prefix).upper() == 'KILO':
                return 1000.0
            # default fallback
            return 1.0
        if u.is_a('IfcConversionBasedUnit') and u.UnitType == 'LENGTHUNIT':
            # ConversionFactor is IfcMeasureWithUnit
            cf = u.ConversionFactor
            if cf and cf.ValueComponent is not None:
                # ValueComponent is IfcLengthMeasure in SI (metre)
                try:
                    return float(cf.ValueComponent)
                except Exception:
                    pass
    return 1.0

