import math

# Find the wall by GlobalId
wall = ifc.by_guid('22hyxvAPr65PFt9WZfHSP3')
if wall is None:
    raise ValueError('Element with given GlobalId not found')

angle = math.radians(90.0)
ca = math.cos(angle)
sa = math.sin(angle)

# Rotation about Z: (x,y) -> (ca*x - sa*y, sa*x + ca*y)
def rot2d(x, y):
    return (ca*x - sa*y, sa*x + ca*y)

def rotate_dir(dir_ent):
    if dir_ent is None:
        return None
    ratios = list(dir_ent.DirectionRatios)
    # Support 2D or 3D direction ratios
    if len(ratios) == 2:
        x, y = ratios
        x2, y2 = rot2d(x, y)
        ratios = [x2, y2]
    elif len(ratios) >= 3:
        x, y, z = ratios[0], ratios[1], ratios[2]
        x2, y2 = rot2d(x, y)
        ratios = [x2, y2, z]
        if len(dir_ent.DirectionRatios) > 3:
            ratios += list(dir_ent.DirectionRatios)[3:]
    dir_ent.DirectionRatios = ratios
    return dir_ent

rotated = {
    'GlobalId': wall.GlobalId,
    'updated': False,
    'method': None,
    'details': {}
}

# Prefer rotating the local placement (Axis2Placement3D) rather than geometry.
placement = getattr(wall, 'ObjectPlacement', None)
if placement and placement.is_a('IfcLocalPlacement'):
    rel = placement.RelativePlacement
    if rel and rel.is_a('IfcAxis2Placement3D'):
        # Rotate RefDirection (local X axis). If missing, assume (1,0,0)
        if rel.RefDirection is None:
            rel.RefDirection = ifc.create_entity('IfcDirection', DirectionRatios=[1.0, 0.0, 0.0])
            rotated['details']['created_RefDirection'] = True
        else:
            rotated['details']['created_RefDirection'] = False

        rotate_dir(rel.RefDirection)

        # Optionally rotate Axis too? Rotation around global Z should not change local Z axis if it's aligned,
        # but if Axis is present and not vertical, rotating around Z is consistent.
        if rel.Axis is not None:
            rotate_dir(rel.Axis)
            rotated['details']['rotated_Axis'] = True
        else:
            rotated['details']['rotated_Axis'] = False

        rotated['updated'] = True
        rotated['method'] = 'IfcLocalPlacement.RelativePlacement(IfcAxis2Placement3D).RefDirection (+Axis if present)'
    elif rel and rel.is_a('IfcAxis2Placement2D'):
        # Rotate 2D placement
        if rel.RefDirection is None:
            rel.RefDirection = ifc.create_entity('IfcDirection', DirectionRatios=[1.0, 0.0])
            rotated['details']['created_RefDirection'] = True
        rotate_dir(rel.RefDirection)
        rotated['updated'] = True
        rotated['method'] = 'IfcLocalPlacement.RelativePlacement(IfcAxis2Placement2D).RefDirection'

# If no object placement, attempt rotating mapped representation transform(s)
if not rotated['updated']:
    rep = getattr(wall, 'Representation', None)
    if rep and rep.is_a('IfcProductDefinitionShape'):
        rotated_any = False
        for shape_rep in rep.Representations or []:
            for item in shape_rep.Items or []:
                if item.is_a('IfcMappedItem'):
                    mt = item.MappingTarget
                    if mt and mt.is_a('IfcCartesianTransformationOperator3D'):
                        # Rotate its Axis1/Axis2 (basis vectors)
                        if mt.Axis1 is not None:
                            rotate_dir(mt.Axis1)
                        if mt.Axis2 is not None:
                            rotate_dir(mt.Axis2)
                        if mt.Axis3 is not None:
                            rotate_dir(mt.Axis3)
                        rotated_any = True
        if rotated_any:
            rotated['updated'] = True
            rotated['method'] = 'IfcMappedItem.MappingTarget axes rotation'

if not rotated['updated']:
    raise ValueError('Could not rotate: no suitable placement or mapped transform found')

commit()
result = rotated

