# Remove the door with a given GlobalId by deleting the element and cleaning up relations
import ifcopenshell

gid = "11kJIqz$n2Jf_DfJV1SDY7"

door = ifc.by_guid(gid)
if not door:
    result = {"status": "not_found", "globalid": gid}
else:
    # Use high-level API removal to handle inverse relationships when possible
    try:
        import ifcopenshell.api as api
        api.run("root.remove_product", ifc, product=door)
        removed_via_api = True
    except Exception as e:
        removed_via_api = False
        api_error = str(e)
        # Fallback: manually remove common relationships then remove entity
        # Collect inverse relationships referencing the door
        inverses = list(ifc.get_inverse(door))
        # Helper to safely remove an entity
        def safe_remove(ent):
            try:
                ifc.remove(ent)
                return True
            except Exception:
                return False
        # Break relations that include this door
        for inv in inverses:
            t = inv.is_a()
            if t == "IfcRelContainedInSpatialStructure":
                # Remove door from RelatedElements; remove relation if empty
                rel_elems = list(inv.RelatedElements or [])
                if door in rel_elems:
                    rel_elems = [e for e in rel_elems if e != door]
                    inv.RelatedElements = rel_elems
                if not inv.RelatedElements:
                    safe_remove(inv)
            elif t == "IfcRelFillsElement":
                # Door fills an opening
                if getattr(inv, "RelatedBuildingElement", None) == door:
                    safe_remove(inv)
            elif t == "IfcRelVoidsElement":
                # Usually points from wall to opening; door isn't part, but handle just in case
                if getattr(inv, "RelatingBuildingElement", None) == door or getattr(inv, "RelatedOpeningElement", None) == door:
                    safe_remove(inv)
            elif t == "IfcRelDefinesByProperties":
                # Remove door from RelatedObjects; keep relation if others remain
                objs = list(inv.RelatedObjects or [])
                if door in objs:
                    inv.RelatedObjects = [o for o in objs if o != door]
                if not inv.RelatedObjects:
                    safe_remove(inv)
            elif t == "IfcRelAssociatesMaterial":
                objs = list(inv.RelatedObjects or [])
                if door in objs:
                    inv.RelatedObjects = [o for o in objs if o != door]
                if not inv.RelatedObjects:
                    safe_remove(inv)
            elif t == "IfcRelDefinesByType":
                objs = list(inv.RelatedObjects or [])
                if door in objs:
                    inv.RelatedObjects = [o for o in objs if o != door]
                if not inv.RelatedObjects:
                    safe_remove(inv)
            elif t == "IfcRelConnectsElements":
                # If connected, remove the relation
                if getattr(inv, "RelatingElement", None) == door or getattr(inv, "RelatedElement", None) == door:
                    safe_remove(inv)
            elif t == "IfcRelNests" or t == "IfcRelAggregates" or t == "IfcRelAssignsToGroup" or t == "IfcRelAssignsToProduct":
                # Remove from related objects and delete relation if empty
                for attr in ("RelatedObjects", "RelatedElements", "RelatedProducts"):
                    if hasattr(inv, attr):
                        lst = list(getattr(inv, attr) or [])
                        if door in lst:
                            setattr(inv, attr, [x for x in lst if x != door])
                # remove if now empty
                empty = False
                for attr in ("RelatedObjects", "RelatedElements", "RelatedProducts"):
                    if hasattr(inv, attr):
                        lst = getattr(inv, attr) or []
                        if len(lst) == 0:
                            empty = True
                if empty:
                    safe_remove(inv)
            elif t == "IfcRelSpaceBoundary":
                # If door referenced in boundary
                if getattr(inv, "RelatedBuildingElement", None) == door:
                    safe_remove(inv)
            # else: leave other inverses

        # Finally remove the door itself
        safe_remove(door)

    # Verify removal
    still_there = ifc.by_guid(gid) is not None
    commit()
    result = {
        "status": "removed" if not still_there else "failed",
        "globalid": gid,
        "removed_via_api": removed_via_api,
        "still_present_after": still_there,
    }
    if not removed_via_api:
        result["api_error"] = api_error

