# Helper to get storey elevation to sort storeys robustly

def get_storey_elevation(st):
    try:
        elev = getattr(st, "Elevation", None)
        if elev is not None:
            return float(elev)
    except Exception:
        pass
    # Fallback: try ObjectPlacement Z
    try:
        op = st.ObjectPlacement
        if op and op.is_a("IfcLocalPlacement"):
            rp = op.RelativePlacement
            if rp and hasattr(rp, "Location") and rp.Location and rp.Location.Coordinates:
                coords = rp.Location.Coordinates
                if len(coords) >= 3:
