    # Unique
    wall_ids = set()
    walls = []
    for w in contained_walls:
        if w.id() not in wall_ids:
            wall_ids.add(w.id())
            walls.append(w)

    for wall in walls:
        changed = False
        old_vals = {}
        # 1) Try to adjust explicit height properties (overall height)
        # Common QTO name: "Height" in IfcElementQuantity; also property set like Pset_WallCommon with "UnconnectedHeight".
        psets = elutil.get_psets(wall, psets_only=False, qtos_only=False) or {}

        # Change in property sets where value is numeric meters
        # Target keys
        targets = [
            ("Pset_WallCommon", "UnconnectedHeight"),
            ("BaseQuantities", "Height"),
            ("Qto_WallBaseQuantities", "Height"),
            ("Qto_WallBaseQuantities", "Length"),  # not change
        ]

        # We'll only adjust known height keys
        for pset_name, prop_name in [("Pset_WallCommon","UnconnectedHeight"), ("BaseQuantities","Height"), ("Qto_WallBaseQuantities","Height")]:
            try:
                if pset_name in psets and prop_name in psets[pset_name]:
                    val = psets[pset_name][prop_name]
                    if isinstance(val, (int, float)):
                        new_val = float(val) - 0.5
                        if new_val < 0:
                            new_val = 0.0
                        # Set the property
                        elutil.set_pset(wall, pset_name, prop_name, new_val)
                        old_vals[f"{pset_name}.{prop_name}"] = val
                        changed = True
            except Exception:
                pass

        # 2) Adjust IfcExtrudedAreaSolid depth if present (most robust for geometry without using geom)
        # Traverse representations to find IfcExtrudedAreaSolid and reduce Depth
        try:
            reps = []
            if wall.Representation and wall.Representation.Representations:
                reps = wall.Representation.Representations
            for rep in reps:
                for item in rep.Items or []:
                    # Sometimes items are IfcMappedItem
                    stack = [item]
                    visited = set()
                    while stack:
                        it = stack.pop()
                        if not it or it.id() in visited:
                            continue
                        visited.add(it.id())
                        if it.is_a("IfcExtrudedAreaSolid"):
                            depth = it.Depth
                            if isinstance(depth, (int, float)):
                                new_depth = float(depth) - 0.5
                                if new_depth < 0:
                                    new_depth = 0.0
                                if new_depth != depth:
                                    old_vals["IfcExtrudedAreaSolid.Depth"] = depth
                                    it.Depth = new_depth
                                    changed = True
                        elif it.is_a("IfcMappedItem"):
                            ms = it.MappingSource
                            if ms and ms.MappedRepresentation:
                                for mi in ms.MappedRepresentation.Items or []:
                                    stack.append(mi)
                        elif it.is_a("IfcBooleanClippingResult"):
                            stack.append(it.FirstOperand)
                            stack.append(it.SecondOperand)
                        elif hasattr(it, "SweptArea") and hasattr(it, "Depth"):
                            # other extrusions
                            try:
                                depth = it.Depth
                                if isinstance(depth, (int, float)):
                                    new_depth = float(depth) - 0.5
                                    if new_depth < 0:
                                        new_depth = 0.0
                                    if new_depth != depth:
                                        old_vals[f"{it.is_a()}.Depth"] = depth
                                        it.Depth = new_depth
                                        changed = True
                            except Exception:
                                pass
        except Exception:
            pass

        if changed:
            modified.append({"wall": wall.GlobalId, "name": wall.Name, "changes": old_vals})
        else:
            skipped.append({"wall": wall.GlobalId, "name": wall.Name})

