def normalize(v):
    x,y,z=v
    l=math.sqrt(x*x+y*y+z*z)
    if l==0:
        return (0.0,0.0,0.0)
    return (x/l,y/l,z/l)

def cross(a,b):
    ax,ay,az=a
    bx,by,bz=b
    return (ay*bz-az*by, az*bx-ax*bz, ax*by-ay*bx)

def dot(a,b):
    return a[0]*b[0]+a[1]*b[1]+a[2]*b[2]

def add(a,b):
    return (a[0]+b[0],a[1]+b[1],a[2]+b[2])

def sub(a,b):
    return (a[0]-b[0],a[1]-b[1],a[2]-b[2])

def mul(v,s):
    return (v[0]*s,v[1]*s,v[2]*s)

def rotate_about_axis(point, axis_point, axis_dir, ang):
    """Rodrigues rotation of point around axis (axis_point + t*axis_dir)."""
    k = normalize(axis_dir)
    p = sub(point, axis_point)
    c = math.cos(ang)
    s = math.sin(ang)
    term1 = mul(p, c)
    term2 = mul(cross(k, p), s)
    term3 = mul(k, dot(k, p) * (1.0 - c))
    pr = add(add(term1, term2), term3)
    return add(pr, axis_point)

def rotate_dir(vec, axis_dir, ang):
    k = normalize(axis_dir)
    v = vec
    c = math.cos(ang)
    s = math.sin(ang)
    term1 = mul(v, c)
    term2 = mul(cross(k, v), s)
    term3 = mul(k, dot(k, v) * (1.0 - c))
    return add(add(term1, term2), term3)

