        return [
            [x[0], y[0], z[0], o[0]],
            [x[1], y[1], z[1], o[1]],
            [x[2], y[2], z[2], o[2]],
            [0.0,  0.0,  0.0,  1.0],
        ]
    def mat_mul(A,B):
        C=[[0.0]*4 for _ in range(4)]
        for i in range(4):
            for j in range(4):
                C[i][j]=sum(A[i][k]*B[k][j] for k in range(4))
