import ifcopenshell
import ifcopenshell.api
from math import sqrt

# Helper functions

def get_obj(gid):
    return ifc.by_guid(gid)

def get_placement_matrix(obj):
    """Return 4x4 placement matrix in world coords for IfcProduct."""
    import ifcopenshell.util.placement as plc
    try:
        return plc.get_local_placement(obj.ObjectPlacement)
    except Exception:
        return None

def mat_mul(a,b):
    res=[[0.0]*4 for _ in range(4)]
    for i in range(4):
        for j in range(4):
            res[i][j]=sum(a[i][k]*b[k][j] for k in range(4))
    return res

def mat_vec(m,v):
    x,y,z=v
    return (
        m[0][0]*x+m[0][1]*y+m[0][2]*z+m[0][3],
        m[1][0]*x+m[1][1]*y+m[1][2]*z+m[1][3],
        m[2][0]*x+m[2][1]*y+m[2][2]*z+m[2][3],
    )

def vec_sub(a,b):
    return (a[0]-b[0],a[1]-b[1],a[2]-b[2])

def vec_add(a,b):
    return (a[0]+b[0],a[1]+b[1],a[2]+b[2])

def vec_dot(a,b):
    return a[0]*b[0]+a[1]*b[1]+a[2]*b[2]

def vec_len(a):
    return sqrt(vec_dot(a,a))

def vec_scale(a,s):
    return (a[0]*s,a[1]*s,a[2]*s)

def vec_norm(a):
    l=vec_len(a)
    if l==0:
        return (0.0,0.0,0.0)
    return (a[0]/l,a[1]/l,a[2]/l)

def dist(a,b):
    return vec_len(vec_sub(a,b))

def unique_points(pts, tol=1e-6):
    out=[]
    for p in pts:
        found=False
        for q in out:
            if dist(p,q) <= tol:
                found=True
                break
        if not found:
            out.append(p)
    return out

def polygon_area_2d(poly):
    # poly: list of (x,y)
    area=0.0
    n=len(poly)
    for i in range(n):
        x1,y1=poly[i]
        x2,y2=poly[(i+1)%n]
        area += x1*y2 - x2*y1
    return area/2.0

def ensure_ccw(poly):
    if polygon_area_2d(poly) < 0:
        return list(reversed(poly))
    return poly

def bbox_of_points(pts):
    xs=[p[0] for p in pts]; ys=[p[1] for p in pts]; zs=[p[2] for p in pts]
    return (min(xs),min(ys),min(zs), max(xs),max(ys),max(zs))

def try_get_profile_points_world(obj):
    """Try to extract 2D footprint points in world coordinates from swept area solids."""
    rep = getattr(obj, 'Representation', None)
    if not rep:
        return []
    # iterate representations
    pts_world=[]
    M = get_placement_matrix(obj)
    if M is None:
        return []
    for r in rep.Representations or []:
        for item in r.Items or []:
            # Handle IfcExtrudedAreaSolid
            if item.is_a('IfcExtrudedAreaSolid'):
                prof = item.SweptArea
                # Profile position relative to solid
                prof_pos = getattr(prof, 'Position', None)
                solid_pos = getattr(item, 'Position', None)
                # build transform: product placement * solid position * profile position
                import ifcopenshell.util.placement as plc
                T = M
                if solid_pos:
                    T = mat_mul(T, plc.get_axis2placement(solid_pos))
                if prof_pos:
                    T = mat_mul(T, plc.get_axis2placement(prof_pos))
                # extract curve points
                if prof.is_a('IfcArbitraryClosedProfileDef'):
                    outer = prof.OuterCurve
                    if outer.is_a('IfcPolyline'):
                        coords=[(p.Coordinates[0], p.Coordinates[1], 0.0) for p in outer.Points]
                        for c in coords:
                            pts_world.append(mat_vec(T,c))
                elif prof.is_a('IfcRectangleProfileDef'):
                    x=prof.XDim; y=prof.YDim
                    coords=[(-x/2,-y/2,0.0),(x/2,-y/2,0.0),(x/2,y/2,0.0),(-x/2,y/2,0.0),(-x/2,-y/2,0.0)]
                    for c in coords:
                        pts_world.append(mat_vec(T,c))
                elif prof.is_a('IfcCircleProfileDef'):
                    # approximate circle with 16 segments
                    import math
                    r=prof.Radius
                    for i in range(16):
                        ang=2*math.pi*i/16
                        c=(r*math.cos(ang), r*math.sin(ang), 0.0)
                        pts_world.append(mat_vec(T,c))
            # Handle IfcFacetedBrep (fallback to vertices)
            if item.is_a('IfcFacetedBrep'):
                # Extract all cartesian points from faces
                pts=[]
                for face in item.Outer.CfsFaces:
                    for bound in face.Bounds:
                        loop = bound.Bound
                        if loop.is_a('IfcPolyLoop'):
                            for cp in loop.Polygon:
                                pts.append((cp.Coordinates[0],cp.Coordinates[1],cp.Coordinates[2]))
                # transform by product placement
                for p in pts:
                    pts_world.append(mat_vec(M,p))
    return pts_world

def get_storey(obj):
    # Try containment
    for rel in ifc.by_type('IfcRelContainedInSpatialStructure'):
        if obj in (rel.RelatedElements or []):
            return rel.RelatingStructure
    return None

