import ifcopenshell
import ifcopenshell.api
from math import atan2

def unit_scale_to_meters(ifc):
    proj = ifc.by_type('IfcProject')
    if not proj:
        return 1.0
    ua = proj[0].UnitsInContext
    if not ua:
        return 1.0
    for u in ua.Units or []:
        if u.is_a('IfcSIUnit') and u.UnitType == 'LENGTHUNIT':
            prefix = u.Prefix
            if prefix is None:
                return 1.0
            return {'MILLI':0.001,'CENTI':0.01,'DECI':0.1,'KILO':1000.0,'MICRO':1e-6}.get(prefix,1.0)
        if u.is_a('IfcConversionBasedUnit') and u.UnitType == 'LENGTHUNIT':
            try:
                return float(u.ConversionFactor.ValueComponent.wrappedValue)
            except Exception:
                return 1.0
    return 1.0


def get_context(ifc):
    ctxs = ifc.by_type('IfcGeometricRepresentationContext')
    if not ctxs:
        return None
    for c in ctxs:
        if c.ContextType in (None, 'Model'):
            return c
    return ctxs[0]


def get_wall_length_height_thickness(wall, scale):
    length = height = thickness = None
    rep = wall.Representation
    if rep:
        for r in rep.Representations or []:
            if r.RepresentationType == 'SweptSolid':
                for item in r.Items or []:
                    if item.is_a('IfcExtrudedAreaSolid'):
                        height = float(item.Depth)
                        prof = item.SweptArea
                        if prof and prof.is_a('IfcRectangleProfileDef'):
                            xdim = float(prof.XDim)
                            ydim = float(prof.YDim)
                            thickness = min(xdim, ydim)
                            length = max(xdim, ydim)
    if height is None:
        height = 2.7 / scale
    if thickness is None:
        thickness = 0.2 / scale
    if length is None:
        length = 4.0 / scale
    return length, height, thickness


def wall_has_openings(wall):
    inv = getattr(wall, 'HasOpenings', None)
    if not inv:
        return False
    for rel in inv:
        if rel and rel.is_a('IfcRelVoidsElement'):
            return True
    return False


def pick_candidate_wall(ifc, scale):
    walls = [w for w in (ifc.by_type('IfcWall') + ifc.by_type('IfcWallStandardCase')) if getattr(w, 'Representation', None)]
    best = None
    best_score = -1e9
    for w in walls:
        L,H,T = get_wall_length_height_thickness(w, scale)
        score = L
        if wall_has_openings(w):
            score += L * 0.2
        if w.ContainedInStructure:
            score += 1.0
        if score > best_score:
            best_score = score
            best = w
    return best


def make_local_placement(ifc, relative_to, x, y, z):
    pt = ifc.create_entity('IfcCartesianPoint', (float(x), float(y), float(z)))
    axis2 = ifc.create_entity('IfcAxis2Placement3D', pt, None, None)
    return ifc.create_entity('IfcLocalPlacement', relative_to, axis2)


scale = unit_scale_to_meters(ifc)
context = get_context(ifc)

wall = pick_candidate_wall(ifc, scale)

# Container
storey = None
if wall and wall.ContainedInStructure:
    storey = wall.ContainedInStructure[0].RelatingStructure
if storey is None:
    s = ifc.by_type('IfcBuildingStorey')
    storey = s[0] if s else None
building = (ifc.by_type('IfcBuilding')[0] if ifc.by_type('IfcBuilding') else None)

# Dimensions
wall_L, wall_H, wall_T = get_wall_length_height_thickness(wall, scale) if wall else (4.0/scale, 2.7/scale, 0.2/scale)

door_w = 0.9/scale

door_h = 2.1/scale
opening_w = min(door_w*1.02, wall_L*0.8)
opening_h = min(door_h*1.01, wall_H*0.95)
opening_depth = wall_T

# Position: mid along wall, at base
offset_along = wall_L*0.5
offset_across = 0.0
offset_z = 0.0

opening = ifcopenshell.api.run('root.create_entity', ifc, ifc_class='IfcOpeningElement', name='Door Opening')
door = ifcopenshell.api.run('root.create_entity', ifc, ifc_class='IfcDoor', name='External Door')

# Placements: create local placement relative to wall placement
if wall and wall.ObjectPlacement:
    opening.ObjectPlacement = make_local_placement(ifc, wall.ObjectPlacement, offset_along, offset_across, offset_z)
    door.ObjectPlacement = make_local_placement(ifc, wall.ObjectPlacement, offset_along, offset_across, offset_z)

# Spatial containment
if storey:
    ifcopenshell.api.run('spatial.assign_container', ifc, products=[door, opening], relating_structure=storey)
elif building:
    ifcopenshell.api.run('spatial.assign_container', ifc, products=[door, opening], relating_structure=building)

# Geometry representations
if context:
    ifcopenshell.api.run('geometry.add_profile_representation', ifc, context=context, product=opening,
                         profile={'profile_type':'AREA','x':opening_depth,'y':opening_w}, depth=opening_h)
    door_thickness = min(wall_T*0.45, 0.05/scale)
    if door_thickness <= 0:
        door_thickness = 0.04/scale
    ifcopenshell.api.run('geometry.add_profile_representation', ifc, context=context, product=door,
                         profile={'profile_type':'AREA','x':door_thickness,'y':opening_w*0.98}, depth=opening_h)

# Attributes
try:
    door.OverallWidth = float(opening_w*0.98)
    door.OverallHeight = float(opening_h)
except Exception:
    pass

# Void and fill
if wall:
    ifcopenshell.api.run('void.add_opening', ifc, opening=opening, element=wall)
    ifcopenshell.api.run('void.add_filling', ifc, opening=opening, element=door)

# Mark external
def ensure_pset_bool(ifc, product, pset_name, prop, val):
    pset = None
    for rel in getattr(product, 'IsDefinedBy', []) or []:
        if rel.is_a('IfcRelDefinesByProperties') and rel.RelatingPropertyDefinition and rel.RelatingPropertyDefinition.is_a('IfcPropertySet'):
            if rel.RelatingPropertyDefinition.Name == pset_name:
                pset = rel.RelatingPropertyDefinition
                break
    if not pset:
        try:
            pset = ifcopenshell.api.run('pset.add_pset', ifc, product=product, name=pset_name)
        except Exception:
            return
    try:
        ifcopenshell.api.run('pset.edit_pset', ifc, pset=pset, properties={prop: bool(val)})
    except Exception:
        pass

ensure_pset_bool(ifc, door, 'Pset_DoorCommon', 'IsExternal', True)

result = {
    'host_wall_global_id': wall.GlobalId if wall else None,
    'opening_global_id': opening.GlobalId,
    'door_global_id': door.GlobalId,
    'opening_size_model_units': {'width': float(opening_w), 'height': float(opening_h), 'depth': float(opening_depth)},
    'unit_scale_m_per_unit': scale,
    'container': storey.Name if storey else (building.Name if building else None)
}

commit()

