def is_slab_close(elem):
    if not elem or not elem.is_a('IfcSlab'):
        return False
    # Filter slabs that are likely bounding elements
    # Accept common PredefinedType values for room-closing slabs
    pt = getattr(elem, 'PredefinedType', None)
    if pt and str(pt) in ('FLOOR','ROOF','BASESLAB','TOPSLAB','USERDEFINED','NOTDEFINED'):
        return True
    # If no predefined type, still accept
    return True

# Collect bounding elements from IfcRelSpaceBoundary (1st and 2nd level)
if room:
    for rel in ifc.get_inverse(room):
        if rel.is_a('IfcRelSpaceBoundary'):
            elem = rel.RelatedBuildingElement
            if is_slab_close(elem):
                gid = elem.GlobalId
                if gid and gid not in slab_gids:
                    slab_gids.append(gid)
        elif rel.is_a('IfcRelAggregates'):
            # sometimes spaces have decomposition; check children boundaries too
            for child in getattr(rel, 'RelatedObjects', []) or []:
                if child.is_a('IfcSpace'):
                    for rel2 in ifc.get_inverse(child):
                        if rel2.is_a('IfcRelSpaceBoundary'):
                            elem = rel2.RelatedBuildingElement
                            if is_slab_close(elem):
                                gid = elem.GlobalId
                                if gid and gid not in slab_gids:
                                    slab_gids.append(gid)

result = slab_gids

import ifcopenshell

room_gid = '3Vyqk8cSj8TOuAk6zHUwKx'
