# Fallback strategy: If no IfcRelSpaceBoundary exists, try to find slabs in the same storey
# as the space and (if available) use IfcRelContainedInSpatialStructure / containment.

slab_gids = []

def add_slab(elem):
    if elem and elem.is_a('IfcSlab'):
        gid = elem.GlobalId
        if gid and gid not in slab_gids:
            slab_gids.append(gid)

if room:
    # 1) Primary: space boundaries
    for rel in ifc.get_inverse(room):
        if rel.is_a('IfcRelSpaceBoundary'):
            add_slab(rel.RelatedBuildingElement)

    # 2) Secondary: slabs connected via IfcRelSpaceBoundary through 2nd level boundaries entities
    if not slab_gids:
        for b in ifc.by_type('IfcRelSpaceBoundary'):
            if getattr(b, 'RelatingSpace', None) == room:
                add_slab(getattr(b, 'RelatedBuildingElement', None))

    # 3) Tertiary: find building storey containing the space, then collect slabs in same storey
    if not slab_gids:
        storey = None
        # IfcRelContainedInSpatialStructure: elements contained in a structure; for space, often via decomposition
        # Space usually is aggregated under a storey through IfcRelAggregates (Spatial decomposition)
        for rel in ifc.get_inverse(room):
            if rel.is_a('IfcRelAggregates'):
                parent = getattr(rel, 'RelatingObject', None)
                if parent and parent.is_a('IfcBuildingStorey'):
                    storey = parent
                    break
        if not storey:
            # search all aggregates to find parent storey
            for rel in ifc.by_type('IfcRelAggregates'):
                if room in (getattr(rel, 'RelatedObjects', []) or []):
                    parent = getattr(rel, 'RelatingObject', None)
                    if parent and parent.is_a('IfcBuildingStorey'):
                        storey = parent
                        break
        if storey:
            # slabs contained in storey
            for rel in ifc.get_inverse(storey):
                if rel.is_a('IfcRelContainedInSpatialStructure'):
                    for e in getattr(rel, 'RelatedElements', []) or []:
                        add_slab(e)

result = slab_gids

