def get_local_placement_xyz(obj):
    # returns (x,y,z) in local placement chain (approx), without full map conversion
    x=y=z=0.0
    pl = getattr(obj, 'ObjectPlacement', None)
    # traverse IfcLocalPlacement
    while pl and pl.is_a('IfcLocalPlacement'):
        rel = pl.RelativePlacement
        if rel and rel.is_a('IfcAxis2Placement3D'):
            loc = rel.Location
            if loc and hasattr(loc, 'Coordinates') and loc.Coordinates:
                coords = list(loc.Coordinates)
                if len(coords) > 0: x += float(coords[0])
                if len(coords) > 1: y += float(coords[1])
                if len(coords) > 2: z += float(coords[2])
        elif rel and rel.is_a('IfcAxis2Placement2D'):
            loc = rel.Location
            if loc and hasattr(loc, 'Coordinates') and loc.Coordinates:
                coords = list(loc.Coordinates)
                if len(coords) > 0: x += float(coords[0])
                if len(coords) > 1: y += float(coords[1])
        pl = getattr(pl, 'PlacementRelTo', None)
    return x,y,z

