def extract_points_from_rep(rep):
    pts=[]
    if not rep:
        return pts
    items = []
    try:
        items = rep.Items or []
    except Exception:
        items = []
    for it in items:
        # SweptSolid with profile
        if it.is_a('IfcExtrudedAreaSolid'):
            prof = it.SweptArea
            if prof and prof.is_a('IfcArbitraryClosedProfileDef'):
                crv = prof.OuterCurve
                if crv and crv.is_a('IfcPolyline'):
                    for p in crv.Points:
                        c = p.Coordinates
                        if len(c)>=2:
                            pts.append((float(c[0]), float(c[1])))
        elif it.is_a('IfcFacetedBrep'):
            # skip
            pass
        elif it.is_a('IfcGeometricCurveSet'):
            for e in it.Elements:
                if e.is_a('IfcPolyline'):
                    for p in e.Points:
                        c=p.Coordinates
                        if len(c)>=2:
                            pts.append((float(c[0]), float(c[1])))
        elif it.is_a('IfcPolyline'):
            for p in it.Points:
                c=p.Coordinates
                if len(c)>=2:
                    pts.append((float(c[0]), float(c[1])))
    return pts

room_pts=[]
