    for rb in rels:
        cg = getattr(rb,'ConnectionGeometry',None)
        if cg and cg.is_a('IfcConnectionSurfaceGeometry'):
            # surface on rel space boundary; often has SurfaceOnRelatingElement as IfcCurveBoundedPlane
            s = cg.SurfaceOnRelatingElement
            # try IfcCurveBoundedPlane outer boundary polyline
            if s and s.is_a('IfcCurveBoundedPlane'):
                ob = s.OuterBoundary
                if ob and ob.is_a('IfcPolyline'):
                    for p in ob.Points:
                        c=p.Coordinates
                        if len(c)>=2:
                            pts.append((float(c[0]),float(c[1])))
    if pts:
        xs=[p[0] for p in pts]
        ys=[p[1] for p in pts]
        room_bbox=(min(xs),min(ys),max(xs),max(ys))

# heuristic search columns if none from boundaries
if not columns:
    # get columns in same storey container if possible
    all_cols = ifc.by_type('IfcColumn')
    # filter by storey containment
    cand=[]
    if storey:
        for c in all_cols:
            try:
                cont = ifcopenshell.util.element.get_container(c)
            except Exception:
                cont = None
            if cont and cont == storey:
                cand.append(c)
    else:
        cand = all_cols

    # If no bbox, just return empty (can't robustly compute touching without geom)
    if room_bbox:
        # expand bbox slightly
        minx,miny,maxx,maxy = room_bbox
        pad = max((maxx-minx),(maxy-miny))*0.01 + 0.05
        minx-=pad; miny-=pad; maxx+=pad; maxy+=pad

        # room placement offset
        rx,ry,rz = get_local_placement_xyz(room)

