            # compare in same coordinate frame (approx). If room rep points are local to room placement, shift bbox.
            # We'll assume rep points are in room local coords -> add room placement.
            c_in = (minx+rx <= cx <= maxx+rx) and (miny+ry <= cy <= maxy+ry)
            if c_in:
                columns.add(c.GlobalId)

result = sorted(columns)
