# Find a room (IfcSpace) that has no adjacency to the given room.
# Adjacency is inferred via IfcRelSpaceBoundary relationships and shared boundary elements.
import ifcopenshell

target_gid = '1mbvTd20X72ePAvoaDnxNU'

def get_space_by_gid(gid):
    objs = ifc.by_guid(gid)
    if objs:
        return objs
    # fallback (older ifcopenshell): iterate
    for s in ifc.by_type('IfcSpace'):
        if getattr(s, 'GlobalId', None) == gid:
            return s
    return None

target = get_space_by_gid(target_gid)
if target is None:
    result = {'error': 'Target space not found', 'target_gid': target_gid}
else:
    # collect boundaries for each space
    # We rely on IfcRelSpaceBoundary: RelatingSpace, RelatedBuildingElement
    boundaries = ifc.by_type('IfcRelSpaceBoundary')

    # Build maps
    space_to_bldg = {}
    bldg_to_spaces = {}
    for rel in boundaries:
        sp = getattr(rel, 'RelatingSpace', None)
        be = getattr(rel, 'RelatedBuildingElement', None)
        if not sp or not be:
            continue
        sg = sp.GlobalId
        bg = be.GlobalId
        space_to_bldg.setdefault(sg, set()).add(bg)
        bldg_to_spaces.setdefault(bg, set()).add(sg)

    tgt_sg = target.GlobalId
    tgt_bldg = space_to_bldg.get(tgt_sg, set())

    # Adjacent spaces are those that share any boundary building element with target
    adjacent = set()
    for bg in tgt_bldg:
        for sg in bldg_to_spaces.get(bg, set()):
            if sg != tgt_sg:
                adjacent.add(sg)

    # Now find a space with no adjacency to target: not in adjacent and also not target
    # If target has no boundaries, then adjacent is empty; choose any other space (if exists)
    candidates = []
    for s in ifc.by_type('IfcSpace'):
        if s.GlobalId == tgt_sg:
            continue
        if s.GlobalId not in adjacent:
            candidates.append(s)

    # Prefer a candidate that also has boundaries (more reliable)
    chosen = None
    for s in candidates:
        if space_to_bldg.get(s.GlobalId):
            chosen = s
            break
    if chosen is None and candidates:
        chosen = candidates[0]

    if chosen is None:
        result = {'error': 'No non-adjacent room found', 'target_gid': tgt_sg, 'adjacent_count': len(adjacent), 'space_count': len(ifc.by_type('IfcSpace'))}
    else:
        result = {'non_adjacent_room_global_id': chosen.GlobalId, 'target_gid': tgt_sg, 'adjacent_count': len(adjacent)}

