import ifcopenshell
from ifcopenshell.util.element import get_psets

# Heuristic: a room (IfcSpace) is considered "open to exterior" if it has a boundary
# (IfcRelSpaceBoundary / 2nd level) whose internal/external flag is EXTERNAL.
# Fallback: check common property sets for indicators.

spaces = ifc.by_type('IfcSpace')
external_spaces = []

def is_external_boundary(rel):
    # IFC2x3/IFC4: IfcRelSpaceBoundary has InternalOrExternalBoundary
    val = getattr(rel, 'InternalOrExternalBoundary', None)
    if val is None:
        return False
    # could be enum string or object; compare robustly
    s = str(val).upper()
    return 'EXTERNAL' in s

# Collect via boundaries
for sp in spaces:
    rels = []
    # IFC4: sp.BoundedBy
    bb = getattr(sp, 'BoundedBy', None)
    if bb:
        rels.extend(list(bb))
    # Also consider inverse via IsDefinedBy etc not needed
    if any(is_external_boundary(r) for r in rels):
        external_spaces.append(sp)

# Fallback via properties if none found
if not external_spaces:
    for sp in spaces:
        psets = get_psets(sp, psets_only=False)
        hit = False
        for psname, ps in psets.items():
            if not isinstance(ps, dict):
                continue
            # look for fields that might indicate exterior exposure
            for k, v in ps.items():
                ks = str(k).lower()
                vs = str(v).lower()
                if 'exterior' in ks or 'external' in ks or 'outside' in ks:
                    if 'true' in vs or 'yes' in vs or 'exterior' in vs or 'external' in vs:
                        hit = True
                        break
            if hit:
                break
        if hit:
            external_spaces.append(sp)

# Choose first if multiple; return all for transparency
result = {
    'count': len(external_spaces),
    'global_ids': [sp.GlobalId for sp in external_spaces],
    'chosen': external_spaces[0].GlobalId if external_spaces else None
}

