# Helpers

def get_local_matrix(product):
    try:
        return plc.get_local_placement(product.ObjectPlacement)
    except Exception:
        return None

def mat_mul(A,B):
    # 4x4
    return [[sum(A[i][k]*B[k][j] for k in range(4)) for j in range(4)] for i in range(4)]

def transform_point(M, p):
    x,y,z=p
    return (
        M[0][0]*x+M[0][1]*y+M[0][2]*z+M[0][3],
        M[1][0]*x+M[1][1]*y+M[1][2]*z+M[1][3],
        M[2][0]*x+M[2][1]*y+M[2][2]*z+M[2][3],
    )

def bbox_union(bbs):
    xs=[bb[0] for bb in bbs]+[bb[3] for bb in bbs]
    ys=[bb[1] for bb in bbs]+[bb[4] for bb in bbs]
    zs=[bb[2] for bb in bbs]+[bb[5] for bb in bbs]
    return (min(xs),min(ys),min(zs),max(xs),max(ys),max(zs))

def bbox_intersects_xy(bb1, bb2):
    return not (bb1[3] < bb2[0] or bb1[0] > bb2[3] or bb1[4] < bb2[1] or bb1[1] > bb2[4])

def bbox_contains_xy(bb_outer, bb_inner):
    return (bb_inner[0] >= bb_outer[0] and bb_inner[3] <= bb_outer[3] and bb_inner[1] >= bb_outer[1] and bb_inner[4] <= bb_outer[4])

def get_product_bbox_local(product):
    # returns bbox in product local coords if possible, else None
    rep = product.Representation
    if not rep:
        return None
    try:
        # Try fast util.shape bounding box without geom
        # Many ifcopenshell versions provide get_bbox for IfcProductRepresentation
        bb = shapeutil.get_bbox(product)
        # get_bbox returns (minx,miny,minz,maxx,maxy,maxz) in world? typically local? If ambiguous, we'll compute by transforming with placement.
        return bb
    except Exception:
        return None

def get_product_bbox_world(product):
    bb = None
    try:
        bb = shapeutil.get_bbox(product)
    except Exception:
        bb = None
    M = get_local_matrix(product)
    if bb is None:
        # fallback: use placement origin only with small epsilon
        if M is None:
            return None
        p = (M[0][3], M[1][3], M[2][3])
        eps=0.01
        return (p[0]-eps,p[1]-eps,p[2]-eps,p[0]+eps,p[1]+eps,p[2]+eps)

    # Determine if bb is already world by checking: if we transform corners and extents explode?
    # Assume bb is in local coords; transform 8 corners.
    if M is None:
        return bb
    minx,miny,minz,maxx,maxy,maxz = bb
    corners=[(minx,miny,minz),(minx,miny,maxz),(minx,maxy,minz),(minx,maxy,maxz),
             (maxx,miny,minz),(maxx,miny,maxz),(maxx,maxy,minz),(maxx,maxy,maxz)]
    pts=[transform_point(M,c) for c in corners]
    xs=[p[0] for p in pts]; ys=[p[1] for p in pts]; zs=[p[2] for p in pts]
    return (min(xs),min(ys),min(zs),max(xs),max(ys),max(zs))

def delete_product(product):
    # remove product and its inverse relationships safely
    ifcopenshell.util.element.remove_deep(ifc, product)

