import math

def _to_float(x):
    try:
        return float(x)
    except Exception:
        return None

def polygon_area_xy(pts):
    # pts: list of (x,y)
    if not pts or len(pts) < 3:
        return 0.0
    a = 0.0
    n = len(pts)
    for i in range(n):
        x1, y1 = pts[i]
        x2, y2 = pts[(i+1) % n]
        a += x1*y2 - x2*y1
    return abs(a) * 0.5

def get_axis2placement2d(pl):
    # returns origin (x,y) and x-axis direction (dx,dy)
    o = (0.0, 0.0)
    xdir = (1.0, 0.0)
    if not pl:
        return o, xdir
    loc = getattr(pl, 'Location', None)
    if loc and hasattr(loc, 'Coordinates') and loc.Coordinates:
        coords = list(loc.Coordinates)
        if len(coords) >= 2:
            o = (float(coords[0]), float(coords[1]))
    ref = getattr(pl, 'RefDirection', None)
    if ref and hasattr(ref, 'DirectionRatios') and ref.DirectionRatios:
        dr = list(ref.DirectionRatios)
        if len(dr) >= 2:
            xdir = (float(dr[0]), float(dr[1]))
            # normalize
            l = math.hypot(xdir[0], xdir[1])
            if l > 1e-12:
                xdir = (xdir[0]/l, xdir[1]/l)
            else:
                xdir = (1.0, 0.0)
    return o, xdir

def transform_2d(pt, origin, xdir):
    # assumes ydir is perpendicular to xdir
    x, y = pt
    ox, oy = origin
    dx, dy = xdir
    # ydir = (-dy, dx)
    return (ox + x*dx + y*(-dy), oy + x*dy + y*dx)

def curve_points_2d(curve):
    # returns list of points in curve's own 2D coordinate system
    t = curve.is_a() if curve else None
    if t == 'IfcPolyline':
        pts = []
        for p in curve.Points:
            c = list(p.Coordinates)
            if len(c) >= 2:
                pts.append((float(c[0]), float(c[1])))
        # if closed polyline may repeat first point; remove last if equal
        if len(pts) > 1 and (abs(pts[0][0]-pts[-1][0])<1e-9 and abs(pts[0][1]-pts[-1][1])<1e-9):
            pts = pts[:-1]
        return pts
    if t == 'IfcCompositeCurve':
        pts_all = []
        for seg in curve.Segments:
            pseg = curve_points_2d(seg.ParentCurve)
            if not pseg:
                continue
            if pts_all:
                # avoid duplicating connecting point
                if abs(pts_all[-1][0]-pseg[0][0])<1e-9 and abs(pts_all[-1][1]-pseg[0][1])<1e-9:
                    pts_all.extend(pseg[1:])
                else:
                    pts_all.extend(pseg)
            else:
                pts_all.extend(pseg)
        return pts_all
    if t == 'IfcTrimmedCurve':
        # handle trimmed line/circle if possible
        base = curve.BasisCurve
        bt = base.is_a() if base else None
        if bt == 'IfcLine':
            pnt = base.Pnt
            dirc = base.Dir
            p0 = (float(pnt.Coordinates[0]), float(pnt.Coordinates[1]))
            d = (float(dirc.DirectionRatios[0]), float(dirc.DirectionRatios[1]))
            dl = math.hypot(d[0], d[1])
            if dl > 1e-12:
                d = (d[0]/dl, d[1]/dl)
            # trims may be IfcParameterValue or IfcCartesianPoint
            def trim_to_param(tr):
                if tr is None:
                    return None
                # IfcParameterValue is real
                if isinstance(tr, (int, float)):
                    return float(tr)
                if hasattr(tr, 'is_a') and tr.is_a() == 'IfcParameterValue':
                    return float(tr.wrappedValue)
                if hasattr(tr, 'Coordinates'):
                    c = list(tr.Coordinates)
                    if len(c) >= 2:
                        # project onto line
                        vx, vy = float(c[0])-p0[0], float(c[1])-p0[1]
                        return vx*d[0] + vy*d[1]
                return None
            t1 = trim_to_param(curve.Trim1[0] if curve.Trim1 else None)
            t2 = trim_to_param(curve.Trim2[0] if curve.Trim2 else None)
            if t1 is None or t2 is None:
                return []
            return [(p0[0]+d[0]*t1, p0[1]+d[1]*t1), (p0[0]+d[0]*t2, p0[1]+d[1]*t2)]
        # other basis types not supported here
        return []
    # IfcIndexedPolyCurve etc could be handled, but keep minimal
    return []

def profile_outer_points(profile):
    if not profile:
        return None
    t = profile.is_a()
    if t == 'IfcArbitraryClosedProfileDef':
        return curve_points_2d(profile.OuterCurve)
    if t == 'IfcArbitraryProfileDefWithVoids':
        return curve_points_2d(profile.OuterCurve)
    if t == 'IfcRectangleProfileDef':
        x = float(profile.XDim)
        y = float(profile.YDim)
        # centered at origin
        return [(-x/2, -y/2), (x/2, -y/2), (x/2, y/2), (-x/2, y/2)]
    if t == 'IfcCircleProfileDef':
        r = float(profile.Radius)
        # approximate with 64-gon
        n=64
        return [(r*math.cos(2*math.pi*i/n), r*math.sin(2*math.pi*i/n)) for i in range(n)]
    return None

def extract_space_net_area(space):
    # 1) Try IfcElementQuantity with NetFloorArea
    for rel in getattr(space, 'IsDefinedBy', []) or []:
        if not rel or rel.is_a() != 'IfcRelDefinesByProperties':
            continue
        propdef = rel.RelatingPropertyDefinition
        if not propdef:
            continue
        if propdef.is_a() == 'IfcElementQuantity':
            for q in propdef.Quantities or []:
                if q and q.is_a() == 'IfcQuantityArea':
                    name = (q.Name or '').lower()
                    if name in ('netfloorarea', 'net floor area', 'net_floor_area'):
                        return float(q.AreaValue)
    # 2) Try IfcPropertySet with NetFloorArea property
    for rel in getattr(space, 'IsDefinedBy', []) or []:
        if not rel or rel.is_a() != 'IfcRelDefinesByProperties':
            continue
        propdef = rel.RelatingPropertyDefinition
        if not propdef:
            continue
        if propdef.is_a() == 'IfcPropertySet':
            for p in propdef.HasProperties or []:
                if not p:
                    continue
                if (p.Name or '').lower() in ('netfloorarea','net floor area','net_floor_area'):
                    nv = getattr(p, 'NominalValue', None)
                    if nv is not None:
                        val = getattr(nv, 'wrappedValue', None)
                        if val is None:
                            try:
                                val = float(nv)
                            except Exception:
                                val = None
                        if val is not None:
                            return float(val)
    # 3) Compute from 2D footprint in representation
    rep = space.Representation
    if not rep:
        return None
    # find IfcShapeRepresentation with type 'FootPrint' or 'GeometricCurveSet' or 'SweptSolid'
    candidates = []
    for r in rep.Representations or []:
        if not r:
            continue
        rep_id = (r.RepresentationIdentifier or '').lower() if hasattr(r,'RepresentationIdentifier') else ''
        rep_type = (r.RepresentationType or '').lower() if hasattr(r,'RepresentationType') else ''
        candidates.append((rep_id, rep_type, r))
    # prioritize footprints
    candidates.sort(key=lambda x: (0 if 'footprint' in x[0] else 1, 0 if 'curve' in x[1] else 1, 0 if 'swept' in x[1] else 1))

    for rep_id, rep_type, r in candidates:
        for item in r.Items or []:
            if not item:
                continue
            it = item.is_a()
            if it == 'IfcExtrudedAreaSolid':
                prof = item.SweptArea
                pts = profile_outer_points(prof)
                if not pts:
                    continue
                # apply profile position if exists (IfcAxis2Placement2D)
                origin, xdir = get_axis2placement2d(getattr(prof, 'Position', None))
                pts2 = [transform_2d(p, origin, xdir) for p in pts]
                return polygon_area_xy(pts2)
            if it == 'IfcFacetedBrep':
                continue
            if it == 'IfcGeometricCurveSet':
                # use first closed polyline-like curve
                for c in item.Elements or []:
                    pts = curve_points_2d(c)
                    if pts and len(pts) >= 3:
                        return polygon_area_xy(pts)
            if it in ('IfcPolyline','IfcCompositeCurve','IfcTrimmedCurve'):
                pts = curve_points_2d(item)
                if pts and len(pts) >= 3:
                    return polygon_area_xy(pts)
            if it == 'IfcMappedItem':
                # try source representation items
                ms = item.MappingSource
                if ms and ms.MappedRepresentation:
                    for mi in ms.MappedRepresentation.Items or []:
                        if mi and mi.is_a() == 'IfcExtrudedAreaSolid':
                            prof = mi.SweptArea
                            pts = profile_outer_points(prof)
                            if not pts:
                                continue
                            origin, xdir = get_axis2placement2d(getattr(prof, 'Position', None))
                            pts2 = [transform_2d(p, origin, xdir) for p in pts]
                            return polygon_area_xy(pts2)
    return None

space = ifc.by_guid('3N9Z0YGDv8JuEhl24cnvVA')
