}

# Compute net floor area (NFA) of all rooms/spaces in the model.
# Strategy:
# - Prefer quantity takeoff: IfcSpace has IfcElementQuantity with area quantities (NetFloorArea / GrossFloorArea / FloorArea / Area).
# - Fallback to IfcQuantityArea named 'NetFloorArea' etc.
# - If no explicit quantities, attempt to use property set 'Pset_SpaceCommon' NetFloorArea.
# - As last resort, compute from 2D footprint polyline if present in Representation (avoid geom).

import ifcopenshell

# Helper: safely get float
def as_float(v):
    try:
        if v is None:
            return None
        return float(v)
    except Exception:
        return None

# Helper: find quantities for an element
def get_area_from_element_quantities(space):
    # Check IsDefinedBy relationships
    areas = []  # list of (priority, name, value)
    for rel in getattr(space, 'IsDefinedBy', []) or []:
        if not rel or not rel.is_a('IfcRelDefinesByProperties'):
            continue
        prop_def = rel.RelatingPropertyDefinition
        if not prop_def:
            continue
        # IfcElementQuantity
        if prop_def.is_a('IfcElementQuantity'):
            for q in prop_def.Quantities or []:
                if not q:
                    continue
                if q.is_a('IfcQuantityArea'):
                    name = (q.Name or '').lower()
                    val = as_float(getattr(q, 'AreaValue', None))
                    if val is None:
                        continue
                    # Priority: net first
                    if 'netfloorarea' in name or (name == 'net area') or ('net' in name and 'floor' in name):
                        pr = 0
                    elif 'floorarea' in name or ('floor' in name and 'area' in name):
                        pr = 1
                    elif 'grossfloorarea' in name or ('gross' in name and 'floor' in name):
                        pr = 2
                    elif name == 'area' or name.endswith('area'):
                        pr = 3
                    else:
                        pr = 4
                    areas.append((pr, q.Name, val))
        # IfcPropertySet
        if prop_def.is_a('IfcPropertySet'):
            # Look for Pset_SpaceCommon.NetFloorArea and similar
            for p in prop_def.HasProperties or []:
                if not p or not p.is_a('IfcPropertySingleValue'):
                    continue
                pname = (p.Name or '').lower()
                if pname in ('netfloorarea', 'net floor area', 'floorarea', 'floor area'):
                    val = as_float(getattr(getattr(p, 'NominalValue', None), 'wrappedValue', None))
                    if val is None:
                        continue
                    pr = 0 if 'net' in pname else 1
                    areas.append((pr, p.Name, val))
    if not areas:
        return None, None
    areas.sort(key=lambda x: x[0])
    return areas[0][2], areas[0][1]

# Fallback geometry: compute area of IfcPolyline/IfcIndexedPolyCurve in a mapped 2D profile if present
def polygon_area(coords):
    # coords: list of (x,y)
    if not coords or len(coords) < 3:
        return None
    area = 0.0
    n = len(coords)
    for i in range(n):
        x1, y1 = coords[i]
        x2, y2 = coords[(i+1)%n]
        area += x1*y2 - x2*y1
    return abs(area) * 0.5

def get_2d_footprint_from_rep(space):
    rep = getattr(space, 'Representation', None)
    if not rep:
        return None
    reps = rep.Representations or []
    for r in reps:
        # Look for footprint or body representations
        rep_id = (getattr(r, 'RepresentationIdentifier', None) or '').lower()
        rep_type = (getattr(r, 'RepresentationType', None) or '').lower()
        items = r.Items or []
        for it in items:
            if not it:
                continue
            # Direct polyline
            if it.is_a('IfcPolyline'):
                pts = []
                for p in it.Points or []:
                    c = getattr(p, 'Coordinates', None)
                    if not c or len(c) < 2:
                        continue
                    pts.append((float(c[0]), float(c[1])))
                if len(pts) >= 3:
                    return pts
            # Indexed polycurve
            if it.is_a('IfcIndexedPolyCurve'):
                pl = it.Points
                if pl and pl.is_a('IfcCartesianPointList2D'):
                    cl = pl.CoordList or []
                    pts = [(float(x), float(y)) for x, y in cl]
                    if len(pts) >= 3:
                        return pts
            # IfcShapeRepresentation could contain IfcExtrudedAreaSolid with IfcArbitraryClosedProfileDef
            if it.is_a('IfcExtrudedAreaSolid'):
                prof = it.SweptArea
                if prof and prof.is_a('IfcArbitraryClosedProfileDef'):
                    curve = prof.OuterCurve
                    if curve and curve.is_a('IfcPolyline'):
                        pts = []
                        for p in curve.Points or []:
                            c = getattr(p, 'Coordinates', None)
                            if not c or len(c) < 2:
                                continue
                            pts.append((float(c[0]), float(c[1])))
                        if len(pts) >= 3:
                            return pts
    return None

spaces = ifc.by_type('IfcSpace')

total_area = 0.0
used = 0
missing = 0
sources = {}

for sp in spaces:
    area, src = get_area_from_element_quantities(sp)
    if area is None:
        # try geometry footprint as last resort
        pts = get_2d_footprint_from_rep(sp)
        if pts is not None:
            area = polygon_area(pts)
            src = 'ComputedFrom2DFootprint'
    if area is None:
        missing += 1
        continue
    total_area += float(area)
    used += 1
    sources[src] = sources.get(src, 0) + 1

result = {
    'net_floor_area_m2': total_area,
    'spaces_total': len(spaces),
    'spaces_with_area': used,
    'spaces_missing_area': missing,
    'area_sources_count': sources,
}

