from collections import defaultdict

def iter_rel_defines_by_props(obj):
    for rel in getattr(obj, "IsDefinedBy", []) or []:
        if rel.is_a("IfcRelDefinesByProperties"):
            yield rel

def get_qty_areas_from_element(obj):
    """Return list of (name, area_value) from quantity sets attached to obj."""
    out = []
    for rel in iter_rel_defines_by_props(obj):
        prop_def = rel.RelatingPropertyDefinition
        if not prop_def:
            continue
        if prop_def.is_a("IfcElementQuantity"):
            for q in prop_def.Quantities or []:
                if q.is_a("IfcQuantityArea") and q.AreaValue is not None:
                    out.append((q.Name, float(q.AreaValue)))
    return out

def get_pset_single_value(obj, pset_name, prop_name):
    for rel in iter_rel_defines_by_props(obj):
        prop_def = rel.RelatingPropertyDefinition
        if not prop_def or not prop_def.is_a("IfcPropertySet"):
            continue
        if prop_def.Name != pset_name:
            continue
        for p in prop_def.HasProperties or []:
            if p.is_a("IfcPropertySingleValue") and p.Name == prop_name:
                nv = p.NominalValue
                if nv is None:
                    return None
                # nv is an IfcValue wrapper; unwrap common numeric types
                try:
                    return float(nv.wrappedValue)
                except Exception:
                    try:
                        return float(nv)
                    except Exception:
                        return None
    return None

def storey_spaces(storey):
    spaces = []
    for rel in getattr(storey, "ContainsElements", []) or []:
        if not rel.is_a("IfcRelContainedInSpatialStructure"):
            continue
        for el in rel.RelatedElements or []:
