TARGET_GIDS = ["1YYXjRkjn7ywhxb576N3hM", "1YYXjRkjn7ywhxb576N3nB", "1YYXjRkjn7ywhxb576N3m0", "1YYXjRkjn7ywhxb576N3gT"]

# Helpers

def get_psets(element):
    """Return dict of pset/qto name -> dict of prop name -> (nominal_value, raw_prop)."""
    out = defaultdict(dict)
    # IsDefinedBy includes IfcRelDefinesByProperties and IfcRelDefinesByType
    for rel in getattr(element, "IsDefinedBy", []) or []:
        if rel.is_a("IfcRelDefinesByProperties"):
            pdef = rel.RelatingPropertyDefinition
            if pdef is None:
                continue
            # Quantity sets
            if pdef.is_a("IfcElementQuantity"):
                qset_name = pdef.Name or ""
                for q in pdef.Quantities or []:
                    name = q.Name
                    val = None
                    # IfcQuantityArea
                    if q.is_a("IfcQuantityArea"):
                        val = q.AreaValue
                    elif hasattr(q, "LengthValue"):
                        val = q.LengthValue
                    elif hasattr(q, "VolumeValue"):
                        val = q.VolumeValue
                    elif hasattr(q, "CountValue"):
                        val = q.CountValue
                    out[qset_name][name] = (val, q)
            # Property sets
            elif pdef.is_a("IfcPropertySet"):
                pset_name = pdef.Name or ""
                for p in pdef.HasProperties or []:
                    name = p.Name
                    val = None
                    if p.is_a("IfcPropertySingleValue"):
                        nv = p.NominalValue
                        if nv is not None:
                            # unwrap IfcValue
                            try:
                                val = float(nv.wrappedValue)
                            except Exception:
                                # might be string
                                val = nv.wrappedValue
                    out[pset_name][name] = (val, p)
        elif rel.is_a("IfcRelDefinesByType"):
            t = rel.RelatingType
            if t is None:
                continue
            for pdef in getattr(t, "HasPropertySets", []) or []:
                if pdef is None:
                    continue
                if pdef.is_a("IfcElementQuantity"):
                    qset_name = pdef.Name or ""
                    for q in pdef.Quantities or []:
                        name = q.Name
                        val = None
                        if q.is_a("IfcQuantityArea"):
                            val = q.AreaValue
                        elif hasattr(q, "LengthValue"):
                            val = q.LengthValue
                        elif hasattr(q, "VolumeValue"):
                            val = q.VolumeValue
                        elif hasattr(q, "CountValue"):
                            val = q.CountValue
                        out[qset_name][name] = (val, q)
                elif pdef.is_a("IfcPropertySet"):
                    pset_name = pdef.Name or ""
                    for p in pdef.HasProperties or []:
                        name = p.Name
                        val = None
                        if p.is_a("IfcPropertySingleValue"):
                            nv = p.NominalValue
                            if nv is not None:
                                try:
                                    val = float(nv.wrappedValue)
                                except Exception:
                                    val = nv.wrappedValue
                        out[pset_name][name] = (val, p)
    return out


def pick_inner_net_area(psets):
    """Try to find an 'inner net wall area' from quantity sets / property sets."""
    # Priority candidates: Qto_WallBaseQuantities.NetSideArea (most relevant), then NetArea
    # Some exports might use 'NetSideArea', 'NetWallArea', 'InnerArea', etc.
    preferred = [
        ("Qto_WallBaseQuantities", ["NetSideArea", "NetArea", "InnerArea", "NetWallArea", "SideArea"]),
        ("BaseQuantities", ["NetSideArea", "NetArea", "SideArea"]),
        ("Qto_WallQuantities", ["NetSideArea", "NetArea"]),
    ]

    for qset, names in preferred:
        if qset in psets:
            for n in names:
                if n in psets[qset]:
                    val, raw = psets[qset][n]
                    if isinstance(val, (int, float)):
                        return float(val), f"{qset}.{n}"

    # Broader search over all sets for likely names
    likely_names = {
        "netsidearea", "netarea", "innerarea", "internalarea", "innersidearea",
        "netwallarea", "areainternal", "area_internal", "insidearea", "internalsidearea"
    }
    for set_name, props in psets.items():
        for prop_name, (val, raw) in props.items():
            key = (prop_name or "").replace(" ", "").replace("_", "").lower()
            if key in likely_names and isinstance(val, (int, float)):
                return float(val), f"{set_name}.{prop_name}"

    return None, None


