# Retrieve outer net wall area for specified walls by GlobalId.
# Strategy:
# 1) Find each IfcWall/IfcWallStandardCase by GlobalId.
# 2) Prefer explicit quantity takeoff: IfcElementQuantity with an IfcQuantityArea named
#    'OuterNetArea'/'Outer Area'/'NetSideArea' etc.
# 3) Otherwise use Pset_WallCommon.NetSideArea if present (less ideal).
# 4) As a last resort, approximate from quantities 'NetArea'/'Area' if clearly tied to outer face (rare).

import re

def norm(s):
    return re.sub(r"\s+", "", (s or "")).lower()

def is_outer_net_name(name):
    n = norm(name)
    # common variants seen in QTO
    keys = [
        'outernetarea', 'outernetwallarea', 'outerarea', 'outerfacearea',
        'netsidearea', 'netexternalsidearea', 'externalnetsidearea',
        'outernetarea(m2)'
    ]
    return any(k in n for k in keys)

def is_net_side_pset(prop_name):
    n = norm(prop_name)
    return n in ('netsidearea', 'netexternalsidearea', 'externalnetsidearea')

def get_qto_outer_net_area(elem):
    areas = []
    # Check IsDefinedBy relationships
    for rel in getattr(elem, 'IsDefinedBy', []) or []:
        pdef = getattr(rel, 'RelatingPropertyDefinition', None)
        if not pdef:
            continue
        # IfcElementQuantity
        if pdef.is_a('IfcElementQuantity'):
            for q in pdef.Quantities or []:
                if q.is_a('IfcQuantityArea'):
                    if is_outer_net_name(q.Name) or is_outer_net_name(getattr(q, 'Description', None)):
                        val = getattr(q, 'AreaValue', None)
                        if isinstance(val, (int, float)):
                            areas.append(val)
        # Some models use IfcPropertySet for QTO-like properties
        if pdef.is_a('IfcPropertySet'):
            for prop in pdef.HasProperties or []:
                if prop.is_a('IfcPropertySingleValue'):
                    pname = prop.Name
                    if is_outer_net_name(pname) or is_outer_net_name(getattr(prop, 'Description', None)):
                        nv = prop.NominalValue
                        if nv is not None and hasattr(nv, 'wrappedValue'):
                            try:
                                areas.append(float(nv.wrappedValue))
                            except Exception:
                                pass
                    # fallback: Pset_WallCommon.NetSideArea
                    if pdef.Name and norm(pdef.Name) == norm('Pset_WallCommon') and is_net_side_pset(pname):
                        nv = prop.NominalValue
                        if nv is not None and hasattr(nv, 'wrappedValue'):
                            try:
                                areas.append(float(nv.wrappedValue))
                            except Exception:
                                pass
    # Prefer maximum if multiple candidates (often gross vs net; outer net tends to be larger than openings-subtracted? not sure)
    if areas:
        # Return a single best guess: choose the first exact 'outernetarea' match if exists
        # otherwise choose max
        return max(areas)
    return None


global_ids = ["1YYXjRkjn7ywhxb576N3hM", "1YYXjRkjn7ywhxb576N3nB", "1YYXjRkjn7ywhxb576N3m0", "1YYXjRkjn7ywhxb576N3gT"]

