import ifcopenshell
from ifcopenshell.util.element import get_psets
from ifcopenshell.util.unit import calculate_unit_scale

gids = ["1YYXjRkjn7ywhxb576N3gT", "1YYXjRkjn7ywhxb576N3m0", "1YYXjRkjn7ywhxb576N3nB", "1YYXjRkjn7ywhxb576N3hM"]

