def get_outer_net_area_m2(wall):
    """Try to obtain outer/net area from quantities or properties.
    Preference:
      1) Qto_WallBaseQuantities -> OuterSurfaceArea / NetSideArea / NetArea / Area
      2) Any Qto_*Wall* quantities with similar names
      3) Property sets for 'Outer net area' like names
    Returns (area_m2, source_str)
    """
    # Helper to convert area to m2. calculate_unit_scale gives length scale, area scale is scale^2.
    area_scale = scale * scale

    # 1) element quantities
    for rel in getattr(wall, 'IsDefinedBy', []) or []:
        prop_def = rel.RelatingPropertyDefinition
        if not prop_def:
            continue
        if prop_def.is_a('IfcElementQuantity'):
            qset_name = (prop_def.Name or '')
            # prioritize wall base quantities
            quantities = list(prop_def.Quantities or [])
            # Build name->quantity
            for q in quantities:
                if not q.is_a('IfcQuantityArea'):
                    continue
                qname = (q.Name or '').lower()
                # prioritize explicit outer surface
                if qset_name == 'Qto_WallBaseQuantities':
                    if qname in ('outersurfacearea', 'outer surface area'):
                        return q.AreaValue * area_scale, f"{qset_name}.{q.Name}"
                # accept other reasonable candidates
            # second pass for candidates
            candidates = []
            for q in quantities:
                if not q.is_a('IfcQuantityArea'):
                    continue
                qname = (q.Name or '').lower()
                if any(k in qname for k in ['outer', 'external']) and any(k in qname for k in ['area', 'surface']):
                    candidates.append((0, q))
                elif any(k in qname for k in ['netsidearea', 'net side area', 'netsurfacearea', 'net surface area']):
                    candidates.append((1, q))
                elif qname in ('netarea', 'net area', 'sidearea', 'side area', 'area'):
                    candidates.append((2, q))
            if candidates:
                candidates.sort(key=lambda x: x[0])
                q = candidates[0][1]
                return q.AreaValue * area_scale, f"{qset_name}.{q.Name}"

    # 2) property sets (less reliable)
    psets = get_psets(wall)
    # search for any property containing outer/net wall area wording
    keys_to_try = []
    for pset_name, props in psets.items():
        if not isinstance(props, dict):
            continue
        for pname, pval in props.items():
            if pval is None:
                continue
            lname = f"{pset_name}.{pname}".lower()
            if 'area' in lname and (('outer' in lname) or ('external' in lname)) and ('net' in lname or 'nets' in lname or True):
                keys_to_try.append((pset_name, pname, pval))
            elif lname.endswith('outersurfacearea') or 'outersurfacearea' in lname:
                keys_to_try.append((pset_name, pname, pval))
    if keys_to_try:
        # take first numeric
        for pset_name, pname, pval in keys_to_try:
            try:
                val = float(pval)
                return val * area_scale, f"{pset_name}.{pname}"
            except:
                pass

    return None, None

