# Compute outer gross wall area (m2) for given wall GlobalIds.
# Strategy:
# 1) Try to read Qto_WallBaseQuantities / Qto_WallCommon / BaseQuantities: OuterSurfaceArea.
# 2) If not present, fallback to gross side area: Length * Height (from quantities), ignoring openings.
# 3) If still missing, approximate from bounding box: max horizontal extent as length, vertical as height.
# Avoid ifcopenshell.geom.

import math

TARGET_GIDS = [
    "1YYXjRkjn7ywhxb576N3gT",
    "1YYXjRkjn7ywhxb576N3m0",
    "1YYXjRkjn7ywhxb576N3nB",
    "1YYXjRkjn7ywhxb576N3hM",
]

def is_number(x):
    try:
        return x is not None and float(x) == float(x)
    except Exception:
        return False

def get_psets_and_qtos(elem):
    rels = getattr(elem, "IsDefinedBy", None) or []
    psets = []
    qtos = []
    for r in rels:
        if not r or not r.is_a("IfcRelDefinesByProperties"):
            continue
        pdef = r.RelatingPropertyDefinition
        if not pdef:
            continue
        if pdef.is_a("IfcElementQuantity"):
            qtos.append(pdef)
        elif pdef.is_a("IfcPropertySet"):
            psets.append(pdef)
    return psets, qtos

def find_quantity_value(qto, names):
    # names: list of candidate quantity names
    if not qto or not getattr(qto, "Quantities", None):
        return None
    for q in qto.Quantities:
        if not q or not getattr(q, "Name", None):
            continue
        if q.Name in names:
            # Handle various IfcPhysicalQuantity subtypes
            for attr in ("AreaValue", "LengthValue", "VolumeValue", "CountValue", "WeightValue", "TimeValue"):
                if hasattr(q, attr):
                    v = getattr(q, attr)
                    if is_number(v):
                        return float(v)
            # IfcQuantity* has .[Type]Value already handled; else None
    return None

def find_prop_value(pset, names):
    if not pset or not getattr(pset, "HasProperties", None):
        return None
    for p in pset.HasProperties:
        if not p or not getattr(p, "Name", None):
            continue
        if p.Name in names and p.is_a("IfcPropertySingleValue"):
            nv = p.NominalValue
            if nv is None:
                continue
            v = getattr(nv, "wrappedValue", None)
            if is_number(v):
                return float(v)
    return None

def get_outer_surface_area_from_qtos(elem):
    psets, qtos = get_psets_and_qtos(elem)
    # Prefer common names
    for qto in qtos:
        if qto.Name in ("Qto_WallBaseQuantities", "Qto_WallCommon", "BaseQuantities"):
            v = find_quantity_value(qto, ["OuterSurfaceArea", "OuterSurface", "OuterArea", "ExternalSurfaceArea", "ExternalArea"])
            if is_number(v):
                return v
    # Search any element quantity
    for qto in qtos:
        v = find_quantity_value(qto, ["OuterSurfaceArea", "ExternalSurfaceArea", "OuterArea", "ExternalArea"])
        if is_number(v):
            return v
    # Sometimes in psets as properties
    for pset in psets:
        if pset.Name and ("Qto_" in pset.Name or "Pset_" in pset.Name):
            v = find_prop_value(pset, ["OuterSurfaceArea", "ExternalSurfaceArea", "OuterArea", "ExternalArea"])
            if is_number(v):
                return v
    return None

def get_length_height_from_qtos(elem):
    psets, qtos = get_psets_and_qtos(elem)
    length = None
    height = None
    # Candidate quantity names
    len_names = ["Length", "OverallLength", "NetLength"]
    h_names = ["Height", "OverallHeight", "NetHeight"]
    for qto in qtos:
        if qto.Name in ("Qto_WallBaseQuantities", "Qto_WallCommon", "BaseQuantities"):
            if length is None:
                length = find_quantity_value(qto, len_names)
            if height is None:
                height = find_quantity_value(qto, h_names)
    for qto in qtos:
        if length is None:
            length = find_quantity_value(qto, len_names)
        if height is None:
            height = find_quantity_value(qto, h_names)
    # Sometimes in psets
    for pset in psets:
        if length is None:
            length = find_prop_value(pset, len_names)
        if height is None:
            height = find_prop_value(pset, h_names)
    return length, height

def get_bbox_from_representation(elem):
    # Lightweight traversal of IfcShapeRepresentation items to compute bbox for extruded solids.
    rep = getattr(elem, "Representation", None)
    if not rep:
        return None
    reps = getattr(rep, "Representations", None) or []
    minx=miny=minz= 1e100
    maxx=maxy=maxz=-1e100
    found=False

    def update_pt(x,y,z):
        nonlocal minx,miny,minz,maxx,maxy,maxz,found
        minx=min(minx,x); miny=min(miny,y); minz=min(minz,z)
        maxx=max(maxx,x); maxy=max(maxy,y); maxz=max(maxz,z)
        found=True

    def handle_profile(profile, depth, pos=None):
        # profile in local coords; pos ignored for extents; depth along +Z
        # Return 2D bbox of profile (x,y), and z [0,depth]
        if profile.is_a("IfcRectangleProfileDef"):
            xdim = float(profile.XDim)
            ydim = float(profile.YDim)
            hx = xdim/2.0
            hy = ydim/2.0
            pts=[(-hx,-hy,0),(hx,-hy,0),(hx,hy,0),(-hx,hy,0)]
            for x,y,_ in pts:
                update_pt(x,y,0)
                update_pt(x,y,depth)
        elif profile.is_a("IfcArbitraryClosedProfileDef"):
            crv = profile.OuterCurve
            # If polyline, use its points
            if crv and crv.is_a("IfcPolyline"):
                pts = crv.Points
                for p in pts:
                    coords = list(p.Coordinates)
                    x=float(coords[0]); y=float(coords[1])
                    update_pt(x,y,0)
                    update_pt(x,y,depth)
        # else: unhandled

    for r in reps:
        items = getattr(r, "Items", None) or []
        for it in items:
            if it.is_a("IfcExtrudedAreaSolid"):
                prof = it.SweptArea
                depth = float(it.Depth) if is_number(it.Depth) else None
                if depth is None:
                    continue
                handle_profile(prof, depth)
            elif it.is_a("IfcBooleanClippingResult"):
                # try get first operand if extruded
                op = it.FirstOperand
                if op and op.is_a("IfcExtrudedAreaSolid"):
                    prof = op.SweptArea
                    depth = float(op.Depth) if is_number(op.Depth) else None
                    if depth is None:
                        continue
                    handle_profile(prof, depth)
    if not found:
        return None
    return (minx,miny,minz,maxx,maxy,maxz)


def approx_length_height_from_bbox(elem):
    bb = get_bbox_from_representation(elem)
    if not bb:
        return None, None
    minx,miny,minz,maxx,maxy,maxz = bb
    dx = maxx-minx
    dy = maxy-miny
    dz = maxz-minz
    # For walls: length is max(dx,dy), thickness min(dx,dy), height dz
    length = max(dx,dy)
    height = dz
    if length <= 0 or height <= 0:
        return None, None
    return length, height

