commit()

# Compute total area of openings (IfcOpeningElement) with area > 2 sqm.
# Prefer existing quantity takeoff (BaseQuantities/Qto_OpeningElementBaseQuantities) Area.
# Fallback: compute from profile/representation for simple swept solids if needed (without ifcopenshell.geom).

import ifcopenshell


def iter_element_quantities(product):
    """Yield (qset_name, quantity) for IfcElementQuantity linked via IfcRelDefinesByProperties."""
    for rel in getattr(product, "IsDefinedBy", []) or []:
        if not rel or not rel.is_a("IfcRelDefinesByProperties"):
            continue
        propdef = rel.RelatingPropertyDefinition
        if not propdef:
            continue
        if propdef.is_a("IfcElementQuantity"):
            qset_name = getattr(propdef, "Name", None)
            for q in propdef.Quantities or []:
                yield qset_name, q


def get_area_from_qtos(opening):
    """Try to get an area quantity in m2 from QTOs."""
    # Prefer standard quantity sets
    preferred_sets = {
        "Qto_OpeningElementBaseQuantities",
        "BaseQuantities",
    }
    # Candidate quantity names
    preferred_names = {
        "Area",
        "GrossArea",
        "NetArea",
        "OpeningArea",
        "CrossSectionArea",
    }

    best = None
    for qset_name, q in iter_element_quantities(opening):
        if not q:
            continue
        if not (q.is_a("IfcQuantityArea") or q.is_a("IfcPhysicalSimpleQuantity")):
            continue
        qname = getattr(q, "Name", "")
        if q.is_a("IfcQuantityArea"):
            val = q.AreaValue
        else:
            # Some models misuse types; attempt common attribute names
            val = getattr(q, "AreaValue", None)
        if val is None:
            continue
        # Score preference
        score = 0
        if qset_name in preferred_sets:
            score += 2
        if qname in preferred_names:
            score += 2
        if qname.lower().endswith("area"):
            score += 1
        # Keep best by score, then by magnitude
        if best is None or score > best[0] or (score == best[0] and float(val) > best[1]):
            best = (score, float(val), qset_name, qname)
    if best:
        return best[1]
    return None


# Unit scaling: IFC length units may not be meters; but QTO area values are typically in project units.
# We'll attempt to determine if length unit is metre; if not, we still assume QTO is in m2 per user request.
# (Most benchmark IFCs store metric quantities.)

openings = ifc.by_type("IfcOpeningElement")
areas = []
for o in openings:
    a = get_area_from_qtos(o)
    if a is None:
        continue
    if a > 2.0:
        areas.append(a)

total_area = sum(areas)
result = {
    "opening_count": len(openings),
    "count_gt_2sqm": len(areas),
    "total_area_gt_2sqm": total_area,
    "areas_gt_2sqm": areas,
}

import ifcopenshell

# Helper to get property by name from a property set

def get_pset_prop_value(obj, prop_names):
    """Return first matching property value from any attached IfcPropertySet.
    prop_names: list of lowercase names to match
    """
    for rel in getattr(obj, 'IsDefinedBy', []) or []:
        if not rel.is_a('IfcRelDefinesByProperties'):
            continue
        pdef = rel.RelatingPropertyDefinition
        if not pdef:
            continue
        if pdef.is_a('IfcPropertySet'):
            for p in pdef.HasProperties or []:
                if not p.is_a('IfcPropertySingleValue'):
                    continue
                nm = (p.Name or '').strip().lower()
                if nm in prop_names:
                    val = p.NominalValue
                    if val is None:
                        continue
                    return getattr(val, 'wrappedValue', val)
    return None


def get_qto_width(obj):
    # Try base quantities: Width
    for rel in getattr(obj, 'IsDefinedBy', []) or []:
        if not rel.is_a('IfcRelDefinesByProperties'):
            continue
        qdef = rel.RelatingPropertyDefinition
        if not qdef:
            continue
        if qdef.is_a('IfcElementQuantity'):
            for q in qdef.Quantities or []:
                if q.is_a('IfcQuantityLength') and (q.Name or '').strip().lower() in ('width', 'overallwidth', 'openingwidth'):
                    return float(q.LengthValue)
    return None


def get_opening_width(opening):
    # Priority: explicit QTO -> OverallWidth in psets -> ObjectType parsing -> bbox (avoid geom)
    w = get_qto_width(opening)
    if w is not None:
        return w
    w = get_pset_prop_value(opening, ['overallwidth', 'width'])
    if w is not None:
        try:
            return float(w)
        except:
            pass
    # Try predefined in some psets for opening/wall
    # Try dimensions in IfcOpeningElement's representation via SweptSolid params without geom
    rep = opening.Representation
    if rep:
        for r in rep.Representations or []:
            for item in r.Items or []:
                # look for IfcExtrudedAreaSolid with IfcRectangleProfileDef
                if item.is_a('IfcExtrudedAreaSolid'):
                    prof = item.SweptArea
                    if prof and prof.is_a('IfcRectangleProfileDef'):
                        try:
                            return float(prof.XDim)
                        except:
                            pass
                # IfcBooleanResult etc - skip
    return None


def opening_has_sill(opening):
    # Interpret "with a sill" as opening (likely window) having a sill height/base offset > 0.
    # Check common properties: SillHeight, Sill Height, SillHeightAboveFloor, WindowSillHeight
    val = get_pset_prop_value(opening, ['sillheight', 'sill height', 'sillheightabovefloor', 'windowsillheight', 'sill_height'])
    if val is not None:
        try:
            return float(val) > 0.0001
        except:
            # if string like '900 mm'
            s = str(val).lower().replace('mm','').strip()
            try:
                return float(s) > 0.0001
            except:
                return True

    # If opening is voided by a window, check that window's Pset_WindowCommon.SillHeight
    for rel in getattr(opening, 'HasFillings', []) or []:
        if not rel.is_a('IfcRelFillsElement'):
            continue
        elem = rel.RelatingBuildingElement
        if not elem:
            continue
        val2 = get_pset_prop_value(elem, ['sillheight', 'sill height', 'sillheightabovefloor', 'windowsillheight', 'sill_height'])
        if val2 is not None:
            try:
                return float(val2) > 0.0001
            except:
                s = str(val2).lower().replace('mm','').strip()
                try:
                    return float(s) > 0.0001
                except:
                    return True
        # If window has predefined type: assume has sill if not a door and placement z > 0
        if elem.is_a('IfcWindow'):
            # try local placement relative z
            pl = elem.ObjectPlacement
            if pl and pl.is_a('IfcLocalPlacement'):
                relpl = pl.RelativePlacement
                if relpl and relpl.is_a('IfcAxis2Placement3D'):
                    loc = relpl.Location
                    if loc and len(loc.Coordinates) >= 3:
                        try:
                            return float(loc.Coordinates[2]) > 0.0001
                        except:
                            pass
            # default assume windows have sill
            return True
    return False


openings = ifc.by_type('IfcOpeningElement')

total_width = 0.0
count = 0
for op in openings:
    if not opening_has_sill(op):
        continue
    w = get_opening_width(op)
    if w is None:
        # as fallback, if filled by window use window overall width
        for rel in getattr(op, 'HasFillings', []) or []:
            if rel.is_a('IfcRelFillsElement'):
                elem = rel.RelatingBuildingElement
                if elem:
                    w2 = get_qto_width(elem)
                    if w2 is None:
                        w2 = get_pset_prop_value(elem, ['overallwidth', 'width'])
                    if w2 is not None:
                        try:
                            w = float(w2)
                        except:
                            w = None
                if w is not None:
                    break
    if w is None:
        continue
    total_width += float(w)
    count += 1

result = {
    'combined_width_m': total_width,
    'openings_with_sill_count': count,
    'total_openings': len(openings)
}

import ifcopenshell

# Collect length of all IfcWall / IfcWallStandardCase in meters.
# Prefer explicit length quantities (IfcElementQuantity/IfcQuantityLength) and avoid geometry.

walls = []
for t in ("IfcWall", "IfcWallStandardCase"):
    walls.extend(ifc.by_type(t) or [])

# Deduplicate in case of subclass overlap
seen = set()
uniq_walls = []
for w in walls:
    if w.id() in seen:
        continue
    seen.add(w.id())
    uniq_walls.append(w)


def to_m(v, unit_name):
    if v is None:
        return None
    u = (unit_name or "").lower()
    if u in ("metre", "meter", "m"):
        return float(v)
    if u in ("millimetre", "millimeter", "mm"):
        return float(v) / 1000.0
    if u in ("centimetre", "centimeter", "cm"):
        return float(v) / 100.0
    if u in ("foot", "feet", "ft"):
        return float(v) * 0.3048
    if u in ("inch", "in"):
        return float(v) * 0.0254
    # Unknown: assume meters
    return float(v)


def find_length_quantity_for_wall(wall):
    # Search quantities via IsDefinedBy relations
    for rel in getattr(wall, "IsDefinedBy", []) or []:
        if not rel or not rel.is_a("IfcRelDefinesByProperties"):
            continue
        pdef = rel.RelatingPropertyDefinition
        if not pdef:
            continue
        # IfcElementQuantity
        if pdef.is_a("IfcElementQuantity"):
            for q in pdef.Quantities or []:
                if not q:
                    continue
                # Direct length quantity
                if q.is_a("IfcQuantityLength"):
                    name = (q.Name or "").lower()
                    # Typical names: Length, NetLength, GrossLength, OverallLength
                    if "length" in name:
                        return float(q.LengthValue)
                # Sometimes stored as IfcPhysicalComplexQuantity etc. Ignore for now.
        # IfcPropertySet with IfcPropertySingleValue
        if pdef.is_a("IfcPropertySet"):
            for prop in pdef.HasProperties or []:
                if not prop or not prop.is_a("IfcPropertySingleValue"):
                    continue
                pname = (prop.Name or "").lower()
                if pname in ("length", "netlength", "overalllength", "grosslength") or ("length" in pname and "" != pname):
                    val = prop.NominalValue
                    if val is None:
                        continue
                    try:
                        # IfcLengthMeasure etc.
                        return float(val.wrappedValue)
                    except Exception:
                        try:
                            return float(val)
                        except Exception:
                            pass
    return None

# Determine model length unit scale to meters
# If project uses conversion-based unit, take conversion factor.
unit_scale_to_m = 1.0
try:
    projects = ifc.by_type("IfcProject")
    if projects:
        uassign = projects[0].UnitsInContext
        if uassign and uassign.Units:
            for u in uassign.Units:
                if not u:
                    continue
                if u.is_a("IfcSIUnit") and u.UnitType == "LENGTHUNIT":
                    # Name is METRE etc; Prefix may be MILLI etc
                    prefix = (u.Prefix or "").upper() if hasattr(u, "Prefix") else ""
                    name = (u.Name or "").upper()
                    if name == "METRE":
                        if prefix == "MILLI":
                            unit_scale_to_m = 0.001
                        elif prefix == "CENTI":
                            unit_scale_to_m = 0.01
                        elif prefix == "DECI":
                            unit_scale_to_m = 0.1
                        elif prefix == "KILO":
                            unit_scale_to_m = 1000.0
                        else:
                            unit_scale_to_m = 1.0
                    break
                if u.is_a("IfcConversionBasedUnit") and u.UnitType == "LENGTHUNIT":
                    # e.g. FOOT. Use conversion factor
                    cf = u.ConversionFactor
                    if cf and cf.ValueComponent:
                        try:
                            # ValueComponent is IfcMeasureWithUnit
                            vc = cf.ValueComponent
                            val = float(getattr(vc, "ValueComponent").wrappedValue)
                            # UnitComponent should be SI unit (metre)
                            unit_scale_to_m = val
                        except Exception:
                            pass
                    break
except Exception:
    unit_scale_to_m = 1.0

# Sum lengths
lengths = []
for w in uniq_walls:
    L = find_length_quantity_for_wall(w)
    if L is None:
        continue
    lengths.append(L * unit_scale_to_m)

total_length_m = sum(lengths)

result = {
    "wall_count": len(uniq_walls),
    "walls_with_length_quantity": len(lengths),
    "total_length_m": total_length_m,
    "unit_scale_to_m": unit_scale_to_m,
}

