import math

# Fallback: compute wall length from geometry parameters without ifcopenshell.geom.
# We try (1) IfcExtrudedAreaSolid depth; (2) polyline axis length (Body/Axis); (3) bounding from SweptSolid.

walls = []
for t in ("IfcWall", "IfcWallStandardCase"):
    walls.extend(ifc.by_type(t) or [])
seen=set(); uniq=[]
for w in walls:
    if w.id() in seen: continue
    seen.add(w.id()); uniq.append(w)

# unit scale to meters (same as before)
unit_scale_to_m = 1.0
try:
    projects = ifc.by_type("IfcProject")
    if projects:
        uassign = projects[0].UnitsInContext
        if uassign and uassign.Units:
            for u in uassign.Units:
                if u and u.is_a("IfcSIUnit") and u.UnitType == "LENGTHUNIT":
                    prefix = (u.Prefix or "").upper() if hasattr(u, "Prefix") else ""
                    name = (u.Name or "").upper()
                    if name == "METRE":
                        unit_scale_to_m = {"MILLI":0.001,"CENTI":0.01,"DECI":0.1,"KILO":1000.0}.get(prefix,1.0)
                    break
                if u and u.is_a("IfcConversionBasedUnit") and u.UnitType == "LENGTHUNIT":
                    cf = u.ConversionFactor
                    if cf and cf.ValueComponent:
                        vc = cf.ValueComponent
                        try:
                            unit_scale_to_m = float(getattr(vc, "ValueComponent").wrappedValue)
                        except Exception:
                            pass
                    break
except Exception:
    unit_scale_to_m = 1.0


def polyline_length(pl):
    pts = pl.Points or []
    if len(pts) < 2:
        return None
    total = 0.0
    prev = pts[0].Coordinates
    for p in pts[1:]:
        c = p.Coordinates
        dx = float(c[0]) - float(prev[0])
        dy = float(c[1]) - float(prev[1])
        dz = (float(c[2]) - float(prev[2])) if len(c) > 2 and len(prev) > 2 else 0.0
        total += math.sqrt(dx*dx+dy*dy+dz*dz)
        prev = c
    return total


def curve_length(curve):
    if curve is None:
        return None
    if curve.is_a("IfcPolyline"):
        return polyline_length(curve)
    # IfcTrimmedCurve etc. not handled
    return None


def find_extrusion_depth(rep):
    # Search representation items for IfcExtrudedAreaSolid and return Depth
    if not rep:
        return None
    for r in rep.Representations or []:
        if not r:
            continue
        for it in r.Items or []:
            if not it:
                continue
            if it.is_a("IfcExtrudedAreaSolid"):
                try:
                    return float(it.Depth)
                except Exception:
                    pass
            if it.is_a("IfcBooleanClippingResult"):
                # The first operand often is an extruded solid
                op = it.FirstOperand
                if op and op.is_a("IfcExtrudedAreaSolid"):
                    try:
                        return float(op.Depth)
                    except Exception:
                        pass
    return None


def find_axis_curve_length(rep):
    if not rep:
        return None
    # Prefer Axis representation
    reps = rep.Representations or []
    for r in reps:
        if not r:
            continue
        rtype = (r.RepresentationType or "").lower()
        rid = (r.RepresentationIdentifier or "").lower()
        if rid == "axis":
            for it in r.Items or []:
                if it and it.is_a("IfcShapeRepresentation"):
                    continue
            for it in r.Items or []:
                if it and it.is_a("IfcCurve2D"):
                    pass
        # Typically Axis is a ShapeRepresentation whose Items include IfcPolyline
        if rid == "axis":
            for it in r.Items or []:
                L = curve_length(it)
                if L:
                    return L
    # Else try any polyline in any representation
    for r in reps:
        if not r:
            continue
        for it in r.Items or []:
            L = curve_length(it)
            if L:
                return L
    return None


lengths_m = []
per_wall = []
for w in uniq:
    rep = getattr(w, "Representation", None)
    L = find_extrusion_depth(rep)
    method = "ExtrudedAreaSolid.Depth" if L is not None else None
    if L is None:
        L = find_axis_curve_length(rep)
        if L is not None:
            method = "Axis/Polyline length"
    if L is None:
        continue
    Lm = L * unit_scale_to_m
    lengths_m.append(Lm)
    per_wall.append((w.GlobalId, Lm, method))

result = {
    "wall_count": len(uniq),
    "walls_with_computed_length": len(lengths_m),
    "total_length_m": sum(lengths_m),
    "per_wall": per_wall,
    "unit_scale_to_m": unit_scale_to_m,
}

