# Compute the area (m^2) of the opening in a slab identified by GlobalId.
# Strategy:
# 1) Find the IfcSlab with given GlobalId.
# 2) Collect its IfcRelVoidsElement relations to IfcOpeningElement(s).
# 3) For each opening, try to compute area from its representation:
#    - Prefer IfcExtrudedAreaSolid swept area (IfcRectangleProfileDef/IfcCircleProfileDef/IfcArbitraryClosedProfileDef).
#    - Fallback to IfcOpeningElement.ObjectPlacement/RefDirection not needed.
#    - If cannot derive, try quantities (IfcElementQuantity -> Qto_OpeningElementBaseQuantities -> Area).
# 4) If multiple openings, sum.
# Assumptions: Units are SI metres; if project uses conversion, apply IfcUnitAssignment scale.

import ifcopenshell

TARGET_GID = "3IVn6KwFj83grW3cy2PbrE"

slab = None
for e in ifc.by_type("IfcSlab"):
    if getattr(e, "GlobalId", None) == TARGET_GID:
        slab = e
        break

if slab is None:
    result = {"error": f"IfcSlab with GlobalId {TARGET_GID} not found"}
else:
    # unit scale to metres
    def get_length_scale_to_m(ifc):
        proj = ifc.by_type("IfcProject")
        if not proj:
            return 1.0
        ua = getattr(proj[0], "UnitsInContext", None)
        if not ua:
            return 1.0
        for u in ua.Units:
            if u.is_a("IfcSIUnit") and u.UnitType == "LENGTHUNIT":
                # SI unit: prefixes possible
                prefix = getattr(u, "Prefix", None)
                name = getattr(u, "Name", None)
                # If name is METRE
                if str(name).upper() == "METRE":
                    mult = 1.0
                    if prefix:
                        p = str(prefix).upper()
                        mult = {
                            "MILLI": 1e-3,
                            "CENTI": 1e-2,
                            "DECI": 1e-1,
                            "DECA": 1e1,
                            "HECTO": 1e2,
                            "KILO": 1e3,
                            "MEGA": 1e6,
                        }.get(p, 1.0)
                    return mult
            if u.is_a("IfcConversionBasedUnit") and u.UnitType == "LENGTHUNIT":
                # Try to read conversion factor
                cf = getattr(u, "ConversionFactor", None)
                if cf and cf.is_a("IfcMeasureWithUnit"):
                    # value component
                    val = getattr(cf, "ValueComponent", None)
                    unit = getattr(cf, "UnitComponent", None)
                    # If unit component is metre-based
                    base = 1.0
                    if unit and unit.is_a("IfcSIUnit") and unit.UnitType == "LENGTHUNIT" and str(unit.Name).upper() == "METRE":
                        prefix = getattr(unit, "Prefix", None)
                        if prefix:
                            p = str(prefix).upper()
                            base = {
                                "MILLI": 1e-3,
                                "CENTI": 1e-2,
                                "DECI": 1e-1,
                                "DECA": 1e1,
                                "HECTO": 1e2,
                                "KILO": 1e3,
                                "MEGA": 1e6,
                            }.get(p, 1.0)
                    # val could be IfcReal/IfcRatioMeasure etc.
                    try:
                        return float(val.wrappedValue) * base
                    except Exception:
                        try:
                            return float(val) * base
                        except Exception:
                            return 1.0
        return 1.0

    L = get_length_scale_to_m(ifc)

    # helpers for profile area
    def poly_area_2d(coords):
        # coords: list of (x,y), assumed closed or not
        if len(coords) < 3:
            return 0.0
        pts = coords[:]
        if pts[0] != pts[-1]:
            pts.append(pts[0])
        s = 0.0
        for i in range(len(pts)-1):
            x1,y1 = pts[i]
            x2,y2 = pts[i+1]
            s += x1*y2 - x2*y1
        return abs(s) * 0.5

    def get_curve_points_2d(curve):
        # Return list of 2D points if curve is polyline
        if curve is None:
            return None
        if curve.is_a("IfcPolyline"):
            pts = []
            for p in curve.Points:
                c = p.Coordinates
                # IfcCartesianPoint can be 2D/3D
                if len(c) >= 2:
                    pts.append((float(c[0]), float(c[1])))
            return pts
        # IfcCompositeCurve etc not handled
        return None

    def area_from_profile(profile):
        if profile is None:
            return None
        if profile.is_a("IfcRectangleProfileDef"):
            x = float(profile.XDim)
            y = float(profile.YDim)
            return x * y
        if profile.is_a("IfcCircleProfileDef"):
            r = float(profile.Radius)
            return 3.141592653589793 * r * r
        if profile.is_a("IfcEllipseProfileDef"):
            a = float(profile.SemiAxis1)
            b = float(profile.SemiAxis2)
            return 3.141592653589793 * a * b
        if profile.is_a("IfcArbitraryClosedProfileDef"):
            pts = get_curve_points_2d(profile.OuterCurve)
            if pts:
                return poly_area_2d(pts)
        if profile.is_a("IfcArbitraryProfileDefWithVoids"):
            outer_pts = get_curve_points_2d(profile.OuterCurve)
            if outer_pts:
                outer = poly_area_2d(outer_pts)
                void_sum = 0.0
                for ic in getattr(profile, "InnerCurves", []) or []:
                    vpts = get_curve_points_2d(ic)
                    if vpts:
                        void_sum += poly_area_2d(vpts)
                return max(outer - void_sum, 0.0)
        return None

    def area_from_representation(elem):
        rep = getattr(elem, "Representation", None)
        if not rep:
            return None
        # Iterate representations and items
        for r in rep.Representations or []:
            for it in r.Items or []:
                # Openings commonly have IfcExtrudedAreaSolid
                if it.is_a("IfcExtrudedAreaSolid"):
                    a = area_from_profile(it.SweptArea)
                    if a is not None:
                        return a
                if it.is_a("IfcBooleanClippingResult"):
                    # Try to dig first operand
                    op = getattr(it, "FirstOperand", None)
                    if op and op.is_a("IfcExtrudedAreaSolid"):
                        a = area_from_profile(op.SweptArea)
                        if a is not None:
                            return a
        return None

    def area_from_quantities(elem):
        # Look for IfcElementQuantity with Area
        for rel in getattr(elem, "IsDefinedBy", []) or []:
            if not rel.is_a("IfcRelDefinesByProperties"):
                continue
            pdef = rel.RelatingPropertyDefinition
            if pdef is None:
                continue
            if pdef.is_a("IfcElementQuantity"):
                for q in pdef.Quantities or []:
                    # try common names
                    if q.is_a("IfcQuantityArea"):
                        try:
                            return float(q.AreaValue)
                        except Exception:
                            pass
            # IfcPropertySet fallback (less likely for area)
        return None

    openings = []
    for rel in getattr(slab, "HasOpenings", []) or []:
        if rel.is_a("IfcRelVoidsElement"):
            op = rel.RelatedOpeningElement
            if op:
                openings.append(op)

    areas_m2 = []
    for op in openings:
        a = area_from_representation(op)
        if a is None:
            a = area_from_quantities(op)
        if a is None:
            # Could be defined as IfcOpeningElement with IfcProductDefinitionShape elsewhere; try mapped rep
            a = area_from_representation(op)
        if a is None:
            areas_m2.append({"opening_gid": op.GlobalId, "area_m2": None, "method": "unresolved"})
        else:
            # convert to m^2
            area_m2 = (a * (L**2))
            areas_m2.append({"opening_gid": op.GlobalId, "area_m2": area_m2, "method": "rep_or_qty"})

    total = 0.0
    unresolved = 0
    for d in areas_m2:
        if d["area_m2"] is None:
            unresolved += 1
        else:
            total += d["area_m2"]

    result = {
        "slab_gid": slab.GlobalId,
        "num_openings": len(openings),
        "openings": areas_m2,
        "total_opening_area_m2_resolved": total,
        "unresolved_openings": unresolved,
        "length_unit_scale_to_m": L,
    }

commit()

# Count all openings (IfcOpeningElement) with area > 2.0 m2
# Approach: prefer explicit quantities (Qto_OpeningElementBaseQuantities / base quantities) via IfcElementQuantity.
# Fallback: compute area from IfcExtrudedAreaSolid profile if available.
# Avoid ifcopenshell.geom.

import ifcopenshell

THRESH = 2.0

def iter_quantity_sets(element):
    # yields IfcElementQuantity instances attached via IfcRelDefinesByProperties
    for rel in getattr(element, 'IsDefinedBy', []) or []:
        if rel.is_a('IfcRelDefinesByProperties'):
            propdef = rel.RelatingPropertyDefinition
            if propdef and propdef.is_a('IfcElementQuantity'):
                yield propdef

def get_area_from_quantities(element):
    # Try common quantity names for opening areas
    candidates = {
        'Area', 'NetArea', 'GrossArea', 'OpeningArea', 'NetSideArea', 'GrossSideArea',
        'CrossSectionArea', 'SectionArea'
    }
    # Also accept any IfcQuantityArea in any quantity set
    best = None
    for qset in iter_quantity_sets(element):
        for q in qset.Quantities or []:
            if q.is_a('IfcQuantityArea'):
                val = float(q.AreaValue)
                # Prefer named candidate if exists, else take max
                if (q.Name or '') in candidates:
                    if best is None or val > best:
                        best = val
                else:
                    if best is None:
                        best = val
                    else:
                        best = max(best, val)
    return best

def poly_area_2d(pts):
    # pts: list of (x,y) tuples
    n = len(pts)
    if n < 3:
        return 0.0
    s = 0.0
    for i in range(n):
        x1, y1 = pts[i]
        x2, y2 = pts[(i+1) % n]
        s += x1*y2 - x2*y1
    return abs(s) * 0.5

def profile_area(profile):
    # Return area in model units^2 (typically m^2 if meters)
    if not profile:
        return None
    if profile.is_a('IfcRectangleProfileDef'):
        return float(profile.XDim) * float(profile.YDim)
    if profile.is_a('IfcCircleProfileDef'):
        r = float(profile.Radius)
        return 3.141592653589793 * r * r
    if profile.is_a('IfcEllipseProfileDef'):
        return 3.141592653589793 * float(profile.SemiAxis1) * float(profile.SemiAxis2)
    if profile.is_a('IfcIShapeProfileDef'):
        # Approx area: flange+web
        return float(profile.OverallWidth) * float(profile.FlangeThickness) * 2 + float(profile.WebThickness) * (float(profile.OverallDepth) - 2*float(profile.FlangeThickness))
    if profile.is_a('IfcArbitraryClosedProfileDef'):
        curve = profile.OuterCurve
        if curve and curve.is_a('IfcPolyline'):
            pts = [(float(p.Coordinates[0]), float(p.Coordinates[1])) for p in curve.Points]
            # If last equals first, drop last
            if len(pts) > 1 and pts[0] == pts[-1]:
                pts = pts[:-1]
            return poly_area_2d(pts)
    if profile.is_a('IfcArbitraryProfileDefWithVoids'):
        outer = None
        if profile.OuterCurve and profile.OuterCurve.is_a('IfcPolyline'):
            pts = [(float(p.Coordinates[0]), float(p.Coordinates[1])) for p in profile.OuterCurve.Points]
            if len(pts) > 1 and pts[0] == pts[-1]:
                pts = pts[:-1]
            outer = poly_area_2d(pts)
        voids = 0.0
        for inner in profile.InnerCurves or []:
            if inner.is_a('IfcPolyline'):
                pts = [(float(p.Coordinates[0]), float(p.Coordinates[1])) for p in inner.Points]
                if len(pts) > 1 and pts[0] == pts[-1]:
                    pts = pts[:-1]
                voids += poly_area_2d(pts)
        if outer is not None:
            return max(0.0, outer - voids)
    return None

def get_area_from_representation(element):
    # For openings, representation may be swept solid; take profile area.
    reps = getattr(element, 'Representation', None)
    if not reps:
        return None
    for rep in reps.Representations or []:
        for item in rep.Items or []:
            if item.is_a('IfcExtrudedAreaSolid'):
                a = profile_area(item.SweptArea)
                if a is not None:
                    return float(a)
            if item.is_a('IfcSweptAreaSolid') and hasattr(item, 'SweptArea'):
                a = profile_area(item.SweptArea)
                if a is not None:
                    return float(a)
    return None

count = 0
unknown = 0
areas = []
for opening in ifc.by_type('IfcOpeningElement'):
    a = get_area_from_quantities(opening)
    if a is None:
        a = get_area_from_representation(opening)
    if a is None:
        unknown += 1
        continue
    areas.append(a)
    if a > THRESH:
        count += 1

result = {
    'opening_count_area_gt_2sqm': count,
    'threshold_sqm': THRESH,
    'openings_total': len(ifc.by_type('IfcOpeningElement')),
    'openings_with_area_found': len(areas),
    'openings_area_unknown': unknown,
    'min_area_found': min(areas) if areas else None,
    'max_area_found': max(areas) if areas else None,
}

import ifcopenshell

slab_gid = "3IVn6KwFj83grW3cy2PbrE"
slab = ifc.by_guid(slab_gid)

# Collect openings related to the slab via IfcRelVoidsElement
openings = []
if slab:
    for rel in getattr(slab, "HasOpenings", []) or []:
        op = getattr(rel, "RelatedOpeningElement", None)
        if op:
            openings.append(op)

# Helper: get a numeric value (assumed in model length units), returning None if not found

def _get_qto(opening):
    # Iterate IsDefinedBy relationships and search for Qto_OpeningElementBaseQuantities / BaseQuantities
    for rel in getattr(opening, "IsDefinedBy", []) or []:
        if not rel or not rel.is_a("IfcRelDefinesByProperties"):
            continue
        ps = rel.RelatingPropertyDefinition
        if not ps:
            continue
        if ps.is_a("IfcElementQuantity"):
            for q in ps.Quantities or []:
                if not q:
                    continue
                if q.is_a("IfcQuantityVolume") and q.Name and q.Name.lower() == "volume":
                    return float(q.VolumeValue)
                # Some exports store as IfcQuantityLength/Area etc; ignore
    return None

# Determine unit scale to meters
scale_to_m = 1.0
try:
    import ifcopenshell.util.unit as unit
    scale_to_m = unit.calculate_unit_scale(ifc)  # scale from model length unit to meters
except Exception:
    # fallback: attempt from IfcUnitAssignment
    scale_to_m = 1.0

vol_sum_m3 = 0.0
volumes_found = []

for op in openings:
    v = _get_qto(op)
    if v is not None:
        # If QTO volume is in cubic model units, convert by scale^3
        v_m3 = v * (scale_to_m ** 3)
        vol_sum_m3 += v_m3
        volumes_found.append((op.GlobalId, v_m3, "QTO"))
    else:
        # Try property sets that might store volume as IfcPropertySingleValue
        found = None
        for rel in getattr(op, "IsDefinedBy", []) or []:
            if not rel or not rel.is_a("IfcRelDefinesByProperties"):
                continue
            pd = rel.RelatingPropertyDefinition
            if not pd:
                continue
            if pd.is_a("IfcPropertySet"):
                for prop in pd.HasProperties or []:
                    if prop and prop.is_a("IfcPropertySingleValue") and prop.Name and prop.Name.lower() in ("volume", "netvolume", "grossvolume"):
                        nv = getattr(prop.NominalValue, "wrappedValue", None)
                        if nv is not None:
                            found = float(nv) * (scale_to_m ** 3)
                            break
                if found is not None:
                    break
        if found is not None:
            vol_sum_m3 += found
            volumes_found.append((op.GlobalId, found, "PSET"))

# If nothing found via QTO/Pset, approximate using bounding boxes from swept solids if available (no geom)
# This is a fallback and may under/over estimate.

def _bbox_volume_from_rep(item):
    # Handle common types: IfcExtrudedAreaSolid (rect/circle)
    if item.is_a("IfcExtrudedAreaSolid"):
        depth = float(item.Depth)
        prof = item.SweptArea
        area = None
        if prof.is_a("IfcRectangleProfileDef"):
            area = float(prof.XDim) * float(prof.YDim)
        elif prof.is_a("IfcCircleProfileDef"):
            r = float(prof.Radius)
            area = 3.141592653589793 * r * r
        elif prof.is_a("IfcArbitraryClosedProfileDef"):
            # compute polygon area if outer curve is IfcPolyline
            oc = prof.OuterCurve
            if oc and oc.is_a("IfcPolyline"):
                pts = oc.Points or []
                coords = [(float(p.Coordinates[0]), float(p.Coordinates[1])) for p in pts]
                if len(coords) >= 3:
                    # ensure closed
                    if coords[0] != coords[-1]:
                        coords.append(coords[0])
                    a = 0.0
                    for i in range(len(coords)-1):
                        x1,y1 = coords[i]
                        x2,y2 = coords[i+1]
                        a += x1*y2 - x2*y1
                    area = abs(a) * 0.5
        if area is not None:
            return area * depth
    return None

if volumes_found == [] and openings:
    for op in openings:
        rep = getattr(op, "Representation", None)
        if not rep:
            continue
        for r in rep.Representations or []:
            for item in r.Items or []:
                v = _bbox_volume_from_rep(item)
                if v is not None:
                    v_m3 = v * (scale_to_m ** 3)
                    vol_sum_m3 += v_m3
                    volumes_found.append((op.GlobalId, v_m3, "REP_APPROX"))
                    break

result = {
    "slab_gid": slab_gid,
    "opening_count": len(openings),
    "volume_m3": vol_sum_m3,
    "per_opening": volumes_found,
    "unit_scale_to_m": scale_to_m,
}

import ifcopenshell

# Goal: net room volume for the non-rectangular room.
# Approach:
# 1) Find spaces (IfcSpace). Prefer ones whose name/longname contains 'non-rect' etc.
# 2) Use quantity sets (IfcElementQuantity) for NetVolume/GrossVolume/Volume.
# 3) If not found, attempt to compute from base area * height from quantities.
# Avoid geometry.

spaces = ifc.by_type('IfcSpace')

def norm(s):
    return (s or '').strip().lower()

def find_qty(element):
    # returns dict of quantities by name (lowercase)
    out = {}
    for rel in getattr(element, 'IsDefinedBy', []) or []:
        propdef = getattr(rel, 'RelatingPropertyDefinition', None)
        if propdef and propdef.is_a('IfcElementQuantity'):
            for q in propdef.Quantities or []:
                name = norm(getattr(q, 'Name', None))
                if not name:
                    continue
                if q.is_a('IfcQuantityVolume'):
                    out[name] = q.VolumeValue
                elif q.is_a('IfcQuantityArea'):
                    out[name] = q.AreaValue
                elif q.is_a('IfcQuantityLength'):
                    out[name] = q.LengthValue
    return out

# Choose candidate: non-rectangular by name/longname/description; else if only one space, use it.
keywords = ['non-rect', 'nonrect', 'non rectangular', 'non-rectangular', 'irregular', 'l-shaped', 'l shaped', 'polygon']

candidates = []
for sp in spaces:
    text = ' '.join([norm(getattr(sp,'Name',None)), norm(getattr(sp,'LongName',None)), norm(getattr(sp,'Description',None))])
    score = sum(1 for k in keywords if k in text)
    if score:
        candidates.append((score, sp))

selected = None
if candidates:
    candidates.sort(key=lambda x: (-x[0], x[1].id()))
    selected = candidates[0][1]
elif len(spaces)==1:
    selected = spaces[0]
else:
    # fallback: pick the space with no rectangular hint? pick largest net volume available
    best = None
    for sp in spaces:
        qty = find_qty(sp)
        # common names
        for key in ['netvolume','net volume','volume','grossvolume','gross volume']:
            if key in qty and qty[key] is not None:
                v = float(qty[key])
                if best is None or v > best[0]:
