}

net_volume = None
basis = None

if selected:
    qty = find_qty(selected)
    # prioritize net volume
    for key in ['netvolume','net volume','net_volume','net room volume','netroomvolume']:
        if key in qty:
            net_volume = qty[key]
            basis = f"quantity:{key}"
            break
    if net_volume is None:
        # next: volume
        for key in ['volume','grossvolume','gross volume','gross_volume']:
            if key in qty:
                net_volume = qty[key]
                basis = f"quantity:{key}"
                break
    if net_volume is None:
        # compute from area * height if available
        area = None
        height = None
        for k in ['netfloorarea','net floor area','floorarea','floor area','area','netarea','net area']:
            if k in qty:
                area = qty[k]
                break
        for k in ['height','roomheight','room height','clearheight','clear height']:
            if k in qty:
                height = qty[k]
                break
        if area is not None and height is not None:
            net_volume = float(area) * float(height)
            basis = f"computed:{k}"

# Ensure float
if net_volume is not None:
    net_volume = float(net_volume)

result = {
    'net_room_volume_m3': net_volume,
