# Second pass: identify the non-rectangular room and derive net volume.
# We'll inspect all IfcSpace names and all attached quantities and property sets.

import ifcopenshell

spaces = ifc.by_type('IfcSpace')

def norm(s):
    return (s or '').strip().lower()

# Extract quantities from IfcElementQuantity and properties from IfcPropertySet

def get_qtos_and_psets(el):
    qtos = []  # (qset_name, q_name, type, value)
    psets = [] # (pset_name, prop_name, type, value)
    for rel in getattr(el, 'IsDefinedBy', []) or []:
        propdef = getattr(rel, 'RelatingPropertyDefinition', None)
        if not propdef:
            continue
        if propdef.is_a('IfcElementQuantity'):
            qset_name = propdef.Name
            for q in propdef.Quantities or []:
                q_name = q.Name
                if q.is_a('IfcQuantityVolume'):
                    qtos.append((qset_name, q_name, 'Volume', q.VolumeValue))
                elif q.is_a('IfcQuantityArea'):
                    qtos.append((qset_name, q_name, 'Area', q.AreaValue))
                elif q.is_a('IfcQuantityLength'):
                    qtos.append((qset_name, q_name, 'Length', q.LengthValue))
                elif q.is_a('IfcQuantityCount'):
                    qtos.append((qset_name, q_name, 'Count', q.CountValue))
                elif q.is_a('IfcQuantityWeight'):
                    qtos.append((qset_name, q_name, 'Weight', q.WeightValue))
                elif q.is_a('IfcQuantityTime'):
                    qtos.append((qset_name, q_name, 'Time', q.TimeValue))
                else:
                    # other quantity types
                    val = None
                    for attr in ['VolumeValue','AreaValue','LengthValue','CountValue','WeightValue','TimeValue']:
                        if hasattr(q, attr):
                            val = getattr(q, attr)
                    qtos.append((qset_name, q_name, q.is_a(), val))
        elif propdef.is_a('IfcPropertySet'):
            pset_name = propdef.Name
            for p in propdef.HasProperties or []:
                if p.is_a('IfcPropertySingleValue'):
                    val = p.NominalValue.wrappedValue if p.NominalValue else None
                    psets.append((pset_name, p.Name, 'SingleValue', val))
                else:
                    psets.append((pset_name, p.Name, p.is_a(), None))
    return qtos, psets

spaces_info = []
for sp in spaces:
    qtos, psets = get_qtos_and_psets(sp)
    spaces_info.append({
        'id': sp.id(),
        'Name': sp.Name,
        'LongName': getattr(sp, 'LongName', None),
        'Description': getattr(sp, 'Description', None),
        'qtos': qtos,
        'psets': psets,
    })

# Try to pick non-rectangular by any hint in text or properties
keywords = ['non-rect', 'nonrect', 'non rectangular', 'non-rectangular', 'irregular', 'l-shaped', 'l shaped', 'polygon']

def score_space(si):
    text = ' '.join([norm(si.get('Name')), norm(si.get('LongName')), norm(si.get('Description'))])
    score = sum(2 for k in keywords if k in text)
    # also look in psets for shape hints
    for pset_name, prop_name, typ, val in si['psets']:
        t = ' '.join([norm(pset_name), norm(prop_name), norm(str(val) if val is not None else '')])
        score += sum(1 for k in keywords if k in t)
    return score

scored = [(score_space(si), si) for si in spaces_info]
scored.sort(key=lambda x: (-x[0], x[1]['id']))

selected = None
if scored and scored[0][0] > 0:
    selected = scored[0][1]
else:
    # fallback: choose space that has any volume quantity; prefer NetVolume-like names
    best = None
    for si in spaces_info:
        for qset_name, q_name, typ, val in si['qtos']:
            if typ == 'Volume' and val is not None:
                name = norm(q_name)
                pri = 2 if 'net' in name else (1 if 'gross' in name or 'volume' in name else 0)
                cand = (pri, float(val), si)
                if best is None or cand[:2] > best[:2]:
                    best = cand
    if best:
        selected = best[2]

net = None
basis = None

if selected:
    # Search quantities for net volume
    for qset_name, q_name, typ, val in selected['qtos']:
        if typ == 'Volume' and val is not None:
            n = norm(q_name)
            if 'net' in n and 'vol' in n:
                net = float(val)
                basis = f"{qset_name}.{q_name}"
                break
    if net is None:
        # try any volume quantity
        for qset_name, q_name, typ, val in selected['qtos']:
            if typ == 'Volume' and val is not None:
                net = float(val)
                basis = f"{qset_name}.{q_name}"
                break
    if net is None:
        # Try properties for volume
        for pset_name, prop_name, typ, val in selected['psets']:
            if val is None:
                continue
            n = norm(prop_name)
            if 'vol' in n:
                try:
                    net = float(val)
                    basis = f"{pset_name}.{prop_name}"
                    break
                except:
                    pass

result = {
    'space_count': len(spaces_info),
    'spaces': [
        {
            'id': si['id'],
            'Name': si['Name'],
            'LongName': si['LongName'],
            'Description': si['Description'],
            'qtos': si['qtos'],
            'psets': si['psets'],
        } for si in spaces_info
    ],
    'selected_space': selected,
    'net_room_volume_m3': net,
    'basis': basis,
}

# Third pass: compute volume from space representation by extracting swept solids (IfcExtrudedAreaSolid)
# without using ifcopenshell.geom.
# We'll compute area of the swept profile (IfcArbitraryClosedProfileDef polyline) and multiply by Depth.

import ifcopenshell

def poly_area(points):
    # points: list of (x,y), closed or not
    if len(points) < 3:
        return 0.0
    # ensure closed
    if points[0] != points[-1]:
        points = points + [points[0]]
    a = 0.0
    for (x1,y1),(x2,y2) in zip(points, points[1:]):
        a += x1*y2 - x2*y1
    return abs(a) * 0.5

def get_2d_points_from_curve(curve):
    # supports IfcPolyline with IfcCartesianPoint
    if curve.is_a('IfcPolyline'):
        pts = []
        for p in curve.Points:
            c = p.Coordinates
            pts.append((float(c[0]), float(c[1])))
        return pts
    return None

def area_from_profile(profile):
    if profile.is_a('IfcArbitraryClosedProfileDef'):
        pts = get_2d_points_from_curve(profile.OuterCurve)
        if pts:
            return poly_area(pts)
    if profile.is_a('IfcRectangleProfileDef'):
        return float(profile.XDim) * float(profile.YDim)
    return None

def volume_from_rep(rep):
    # rep: IfcProductRepresentation
    if not rep:
        return None
    total = 0.0
    found = False
    for r in rep.Representations or []:
        for item in r.Items or []:
            if item.is_a('IfcExtrudedAreaSolid'):
                a = area_from_profile(item.SweptArea)
                if a is None:
                    continue
                depth = float(item.Depth)
                total += a * depth
                found = True
    return total if found else None

spaces = ifc.by_type('IfcSpace')

volumes = []
for sp in spaces:
    v = volume_from_rep(getattr(sp, 'Representation', None))
    volumes.append((sp, v))

# identify non-rectangular: prefer profile not rectangle (i.e., arbitrary closed)
nonrect = []
for sp in spaces:
    rep = getattr(sp,'Representation',None)
    if not rep:
        continue
    for r in rep.Representations or []:
        for item in r.Items or []:
            if item.is_a('IfcExtrudedAreaSolid'):
                if item.SweptArea and item.SweptArea.is_a('IfcArbitraryClosedProfileDef'):
                    nonrect.append(sp)
                    break
        if sp in nonrect:
            break

selected = None
if nonrect:
    # if multiple, pick the one with largest computed volume
    best = None
    for sp in nonrect:
        v = volume_from_rep(sp.Representation)
        if v is None:
            continue
        if best is None or v > best[0]:
            best = (v, sp)
    if best:
        selected = best[1]
        net = best[0]
    else:
        selected = nonrect[0]
        net = volume_from_rep(selected.Representation)
else:
    # fallback: largest computed volume
    best = None
    for sp,v in volumes:
        if v is None:
            continue
        if best is None or v > best[0]:
            best = (v, sp)
    if best:
        net, selected = best[0], best[1]
    else:
        net, selected = None, None

result = {
    'net_room_volume_m3': float(net) if net is not None else None,
    'selected_space_id': selected.id() if selected else None,
    'selected_space_name': getattr(selected,'Name',None) if selected else None,
    'selected_space_longname': getattr(selected,'LongName',None) if selected else None,
    'all_space_volumes_m3': [
        {
            'id': sp.id(),
            'Name': sp.Name,
            'LongName': getattr(sp,'LongName',None),
            'volume_m3': float(v) if v is not None else None
        } for sp,v in volumes
    ],
    'nonrect_space_ids': [sp.id() for sp in nonrect],
    'basis': 'computed_from_IfcExtrudedAreaSolid_profile_area_x_depth (no geom)'
}

import ifcopenshell

# Collect net volumes for all slabs.
# Strategy (no geom):
# 1) Prefer IfcElementQuantity with a QuantityVolume named like NetVolume/Volume.
# 2) Else use IfcPropertySingleValue named NetVolume/Volume.
# 3) Else if base quantities exist in Qto_SlabBaseQuantities, use NetVolume/GrossVolume.
# 4) Else fallback to 0.

slabs = ifc.by_type('IfcSlab')

def _to_float(val):
    if val is None:
        return None
    # IfcOpenShell wraps numbers in simple types with .wrappedValue
    if hasattr(val, 'wrappedValue'):
        val = val.wrappedValue
    try:
        return float(val)
    except Exception:
        return None

VOL_NAMES = {
    'netvolume', 'net volume', 'net_vol', 'netvol',
    'volume', 'vol',
    'grossvolume', 'gross volume'
}

def find_volume_in_quantities(quantities):
    # quantities: list of IfcPhysicalQuantity
    net = None
    gross = None
    anyv = None
    for q in quantities or []:
        if not q:
            continue
        qname = (q.Name or '').strip().lower()
        if q.is_a('IfcQuantityVolume'):
            v = _to_float(q.VolumeValue)
            if v is None:
                continue
            anyv = v if anyv is None else anyv
            if 'net' in qname:
                net = v
            if 'gross' in qname:
                gross = v
            if qname in ('volume',):
                # sometimes only Volume is given and is effectively net
                if net is None:
                    net = v
        # Some exports store as IfcQuantityLength/Area etc, ignore.
    if net is not None:
        return net
    if anyv is not None:
        return anyv
    if gross is not None:
        return gross
    return None

def find_volume_in_pset(pset):
    # pset: IfcPropertySet
    net = None
    anyv = None
    for p in pset.HasProperties or []:
        pname = (p.Name or '').strip().lower()
        if pname not in VOL_NAMES and ('volume' not in pname and 'net' not in pname and 'gross' not in pname):
            continue
        if p.is_a('IfcPropertySingleValue'):
            v = _to_float(p.NominalValue)
            if v is None:
                continue
            anyv = v if anyv is None else anyv
            if 'net' in pname:
                net = v
            elif pname in ('volume',):
                if net is None:
                    net = v
    return net if net is not None else anyv

def slab_net_volume(slab):
    # Scan IsDefinedBy relationships
    net_candidates = []
    for rel in getattr(slab, 'IsDefinedBy', []) or []:
        if not rel or not rel.is_a('IfcRelDefinesByProperties'):
            continue
        pdef = rel.RelatingPropertyDefinition
        if not pdef:
            continue
        # IfcElementQuantity
        if pdef.is_a('IfcElementQuantity'):
            qset_name = (pdef.Name or '').strip().lower()
            v = find_volume_in_quantities(pdef.Quantities)
            if v is not None:
                # Prefer base quantity set names when present
                score = 0
                if 'qto_slabbasequantities' in qset_name:
                    score += 10
                if 'basequantities' in qset_name:
                    score += 5
                net_candidates.append((score, v))
        # IfcPropertySet
        elif pdef.is_a('IfcPropertySet'):
            pset_name = (pdef.Name or '').strip().lower()
            v = find_volume_in_pset(pdef)
            if v is not None:
                score = 0
                if 'qto_' in pset_name:
                    score += 2
                if 'basequantities' in pset_name:
                    score += 5
                if 'net' in pset_name:
                    score += 1
                net_candidates.append((score, v))

    if net_candidates:
        # pick highest score, then first
        net_candidates.sort(key=lambda x: x[0], reverse=True)
        return net_candidates[0][1]
    return 0.0

total = 0.0
per_slab = []
for s in slabs:
    v = slab_net_volume(s)
    if v is None:
        v = 0.0
    total += float(v)
    per_slab.append((s.GlobalId, s.Name, float(v)))

result = {
    'slab_count': len(slabs),
    'total_net_volume_m3': total,
    'per_slab': per_slab[:50],  # limit for debugging
}

import math

# Goal: perimeter (linear, m) of all rooms/spaces. User asked "in cubic meters" but perimeter is length.
# We'll compute perimeter in meters and return, noting unit.

# --- Unit handling ---

def get_length_unit_scale_to_m(ifc):
    # Returns scale factor to convert IFC length units to meters.
    # Default: meters.
    proj = ifc.by_type('IfcProject')
    if not proj:
        return 1.0
    proj = proj[0]
    units = None
    try:
        units = proj.UnitsInContext.Units
    except Exception:
        units = None
    if not units:
        return 1.0
    for u in units:
        if u.is_a('IfcSIUnit') and u.UnitType == 'LENGTHUNIT':
            # Name can be METRE; Prefix can be MILLI, CENTI, DECI, etc.
            prefix = (u.Prefix or '').upper() if hasattr(u, 'Prefix') else ''
            name = (u.Name or '').upper() if hasattr(u, 'Name') else ''
            if name in ('METRE','METER'):
                return {
                    '': 1.0,
                    None: 1.0,
                    'MILLI': 0.001,
                    'CENTI': 0.01,
                    'DECI': 0.1,
                    'KILO': 1000.0,
                }.get(prefix if prefix != '' else '', 1.0)
    # IfcConversionBasedUnit
    for u in units:
        if u.is_a('IfcConversionBasedUnit') and u.UnitType == 'LENGTHUNIT':
            # Try to evaluate conversion factor value component to SI base
            try:
                cf = u.ConversionFactor
                # IfcMeasureWithUnit: ValueComponent (IfcLengthMeasure) * UnitComponent
                val = float(cf.ValueComponent.wrappedValue)
                # UnitComponent could be an IfcSIUnit metre with prefix
                unit_comp = cf.UnitComponent
                if unit_comp and unit_comp.is_a('IfcSIUnit') and unit_comp.UnitType=='LENGTHUNIT':
                    prefix = (unit_comp.Prefix or '').upper() if hasattr(unit_comp, 'Prefix') else ''
                    name = (unit_comp.Name or '').upper() if hasattr(unit_comp, 'Name') else ''
                    if name in ('METRE','METER'):
                        m = {
                            '': 1.0,
                            None: 1.0,
                            'MILLI': 0.001,
                            'CENTI': 0.01,
                            'DECI': 0.1,
                            'KILO': 1000.0,
                        }.get(prefix if prefix != '' else '', 1.0)
                        return val * m
            except Exception:
                pass
    return 1.0

scale = get_length_unit_scale_to_m(ifc)

# --- Geometry extraction from IfcSpace ---

def points_from_ifccartesianpoint_list(cps):
    pts=[]
    for cp in cps:
        try:
            coords = cp.Coordinates
            x=float(coords[0]); y=float(coords[1])
            pts.append((x,y))
        except Exception:
            continue
    return pts


def extract_2d_loops_from_representation(rep):
    # returns list of loops, each loop is list of (x,y) in representation coordinates
    loops=[]
    if not rep:
        return loops
    items = getattr(rep, 'Items', None)
    if not items:
        return loops
    for it in items:
        if it.is_a('IfcShapeRepresentation'):
            # dive into nested
            loops += extract_2d_loops_from_representation(it)
        elif it.is_a('IfcGeometricRepresentationItem'):
            # Handle IfcPolyline directly
            if it.is_a('IfcPolyline'):
                pts = points_from_ifccartesianpoint_list(it.Points)
                if len(pts) >= 3:
                    loops.append(pts)
            # Handle IfcCompositeCurve? (approx using its segments if polylines)
            elif it.is_a('IfcCompositeCurve'):
                pts=[]
                ok=True
                for seg in it.Segments:
                    pc = seg.ParentCurve
                    if pc.is_a('IfcPolyline'):
                        segpts = points_from_ifccartesianpoint_list(pc.Points)
                        if not segpts:
                            ok=False; break
                        if pts and segpts:
                            # avoid duplicate joint
                            if pts[-1]==segpts[0]:
                                pts += segpts[1:]
                            else:
                                pts += segpts
                        else:
                            pts += segpts
                    else:
                        ok=False; break
                if ok and len(pts)>=3:
                    loops.append(pts)
            # Handle IfcIndexedPolyCurve
            elif it.is_a('IfcIndexedPolyCurve'):
                # Points: IfcCartesianPointList2D
                pl = it.Points
                coord_list = getattr(pl, 'CoordList', None)
                if coord_list:
                    # map index -> point
                    base=[(float(c[0]), float(c[1])) for c in coord_list]
                    # IfcIndexedPolyCurve may have Segments; if none, uses all points in order
                    if it.Segments:
                        pts=[]
                        for seg in it.Segments:
                            # IfcLineIndex or IfcArcIndex
                            idx = list(seg.wrappedValue) if hasattr(seg,'wrappedValue') else list(seg)
                            # 1-based indices
                            for j,i in enumerate(idx):
                                p=base[int(i)-1]
                                if pts and p==pts[-1]:
                                    continue
                                pts.append(p)
                        if len(pts)>=3:
                            loops.append(pts)
                    else:
                        if len(base)>=3:
                            loops.append(base)
            # Handle IfcArbitraryClosedProfileDef via IfcExtrudedAreaSolid etc.
            elif it.is_a('IfcExtrudedAreaSolid'):
                prof = it.SweptArea
                if prof and prof.is_a('IfcArbitraryClosedProfileDef'):
                    crv = prof.OuterCurve
                    # recurse as if item
                    if crv and crv.is_a('IfcPolyline'):
                        pts = points_from_ifccartesianpoint_list(crv.Points)
                        if len(pts)>=3:
                            loops.append(pts)
                    elif crv and crv.is_a('IfcIndexedPolyCurve'):
                        # mimic above
                        pl = crv.Points
                        coord_list = getattr(pl,'CoordList',None)
                        if coord_list:
                            base=[(float(c[0]), float(c[1])) for c in coord_list]
                            if crv.Segments:
                                pts=[]
                                for seg in crv.Segments:
                                    idx = list(seg.wrappedValue) if hasattr(seg,'wrappedValue') else list(seg)
                                    for i in idx:
                                        p=base[int(i)-1]
                                        if pts and p==pts[-1]:
                                            continue
                                        pts.append(p)
                                if len(pts)>=3:
                                    loops.append(pts)
                            else:
                                if len(base)>=3:
                                    loops.append(base)
        # Other container types
        elif hasattr(it, 'Items'):
            loops += extract_2d_loops_from_representation(it)
    return loops


def extract_space_footprint_loops(space):
    # Prefer 2D footprint representations
    loops=[]
    reps=[]
    try:
        if space.Representation and space.Representation.Representations:
            reps = list(space.Representation.Representations)
    except Exception:
        reps=[]

    # Look for FootPrint / Plan
    for r in reps:
        rid = (getattr(r,'RepresentationIdentifier',None) or '')
        rtype = (getattr(r,'RepresentationType',None) or '')
        if str(rid).lower() in ('footprint','plan') or str(rtype).lower() in ('curve2d','geometriccurveSet'.lower()):
            loops += extract_2d_loops_from_representation(r)

    if loops:
        return loops

    # Fallback: try any representation for polylines / swept profiles
    for r in reps:
        loops += extract_2d_loops_from_representation(r)
    return loops


def perimeter_of_loop(loop):
    # loop: list of (x,y). If not explicitly closed, close.
    if len(loop)<3:
        return 0.0
    per=0.0
    pts=list(loop)
    if pts[0]!=pts[-1]:
        pts.append(pts[0])
    for i in range(len(pts)-1):
        dx=pts[i+1][0]-pts[i][0]
        dy=pts[i+1][1]-pts[i][1]
        per += math.hypot(dx,dy)
    return per

spaces = ifc.by_type('IfcSpace')
room_perimeters=[]

total=0.0
for sp in spaces:
    loops = extract_space_footprint_loops(sp)
    per_local=0.0
    if loops:
        # choose largest perimeter loop as outer boundary
        pers=[perimeter_of_loop(l) for l in loops]
        per_local=max(pers) if pers else 0.0
    # convert to meters
    per_m = per_local * scale
    total += per_m
    name = (sp.LongName or sp.Name or '')
    room_perimeters.append({'GlobalId': sp.GlobalId, 'Name': name, 'Perimeter_m': per_m})

result = {
    'total_rooms': len(spaces),
    'unit_scale_to_m': scale,
    'total_perimeter_m': total,
    'rooms': room_perimeters[:],
    'note': 'Perimeter is a length (m). The request said cubic meters; that unit is not applicable to perimeter.'
}

