import ifcopenshell
import re

# Helper: collect candidate strings from an entity (name, longname, description, psets)
def get_strings_for_obj(obj):
    strs = []
    for attr in ["Name", "LongName", "Description", "ObjectType"]:
        try:
            v = getattr(obj, attr, None)
            if isinstance(v, str) and v:
                strs.append(v)
        except Exception:
            pass
    # Property sets
    try:
        for rel in getattr(obj, "IsDefinedBy", []) or []:
            if not rel or not rel.is_a("IfcRelDefinesByProperties"):
                continue
            pdef = rel.RelatingPropertyDefinition
            if not pdef:
                continue
            if pdef.is_a("IfcPropertySet"):
                for prop in pdef.HasProperties or []:
                    if not prop:
                        continue
                    if prop.is_a("IfcPropertySingleValue"):
                        name = prop.Name
                        val = prop.NominalValue
                        if isinstance(name, str) and name:
                            strs.append(name)
                        if val is not None:
                            # unwrap
                            try:
                                if hasattr(val, "wrappedValue"):
                                    v = val.wrappedValue
                                else:
                                    v = val
                                if isinstance(v, str) and v:
                                    strs.append(v)
                            except Exception:
                                pass
            # Some files use IfcElementQuantity etc; ignore
    except Exception:
        pass
    return strs

keywords = [
    "spatially soft",
    "spatial soft",
    "soft walls",
    "soft surrounding walls",
    "surrounding walls are perceived as spatially soft",
    "spatially_soft",
    "spatialSoft",
]

# Search IfcSpace first
candidates = []
for sp in ifc.by_type("IfcSpace"):
    text = " | ".join(get_strings_for_obj(sp)).lower()
    for kw in keywords:
        if kw in text:
            candidates.append(sp)
            break

# If none found on spaces, search annotations/relationships that might tag the space
if not candidates:
    # Search all entities with GlobalId and strings containing keywords; then try to find referenced space
    matches = []
    # iterate common types
    for t in ["IfcSpace", "IfcAnnotation", "IfcGroup", "IfcZone", "IfcRelAssignsToGroup", "IfcRelAssociates", "IfcPropertySet"]:
        for obj in ifc.by_type(t):
            # skip pset since handled differently
            if t == "IfcPropertySet":
                # check pset name and property values
                pset = obj
                ptxt = " ".join([pset.Name or ""] + [p.Name or "" for p in (pset.HasProperties or [])])
                ptxt = ptxt.lower()
                if any(kw in ptxt for kw in keywords):
                    matches.append(pset)
                continue
            try:
                text = " | ".join(get_strings_for_obj(obj)).lower()
            except Exception:
                continue
            if any(kw in text for kw in keywords):
                matches.append(obj)

    # attempt to resolve space from matches
    for m in matches:
        # If it's already a space
        if hasattr(m, "is_a") and m.is_a("IfcSpace"):
            candidates.append(m)
            continue
        # If group/zone: check assigned objects
        if hasattr(m, "is_a") and m.is_a("IfcGroup"):
            try:
                for rel in m.IsGroupedBy or []:
                    for obj in rel.RelatedObjects or []:
                        if obj and obj.is_a("IfcSpace"):
                            candidates.append(obj)
            except Exception:
                pass
        # If rel assigns to group, see related objects
        if hasattr(m, "is_a") and m.is_a("IfcRelAssignsToGroup"):
            try:
                for obj in m.RelatedObjects or []:
                    if obj and obj.is_a("IfcSpace"):
                        candidates.append(obj)
            except Exception:
                pass

# Deduplicate
seen = set()
uniq = []
for sp in candidates:
    gid = getattr(sp, "GlobalId", None)
    if gid and gid not in seen:
        seen.add(gid)
        uniq.append(sp)

# If still none, fallback heuristic: look for any space with a property named like that
if not uniq:
    pattern = re.compile(r"spatially\s*soft|soft", re.I)
    for sp in ifc.by_type("IfcSpace"):
        strs = get_strings_for_obj(sp)
        if any(pattern.search(s or "") for s in strs):
            uniq.append(sp)
            break

result = None
if uniq:
    # If multiple, choose the one with the most keyword hits
    best = None
    best_score = -1
    for sp in uniq:
        text = " | ".join(get_strings_for_obj(sp)).lower()
        score = sum(text.count(kw) for kw in keywords)
        if score > best_score:
            best_score = score
            best = sp
    result = {
        "global_id": best.GlobalId,
        "name": getattr(best, "Name", None),
        "long_name": getattr(best, "LongName", None),
        "description": getattr(best, "Description", None),
    }
else:
    result = {"global_id": None, "note": "No IfcSpace found with keywords indicating 'spatially soft' surrounding walls."}

