def unwrap(v):
    if v is None:
        return None
    try:
        return v.wrappedValue
    except Exception:
        return v

def pset_text(obj):
    out = []
    for rel in getattr(obj, "IsDefinedBy", []) or []:
        if not rel or not rel.is_a("IfcRelDefinesByProperties"):
            continue
        pdef = rel.RelatingPropertyDefinition
        if not pdef or not pdef.is_a("IfcPropertySet"):
            continue
        if pdef.Name:
            out.append(pdef.Name)
        for p in pdef.HasProperties or []:
            if not p:
                continue
            if p.is_a("IfcPropertySingleValue"):
                if p.Name:
                    out.append(p.Name)
                val = unwrap(p.NominalValue)
                if isinstance(val, str) and val:
                    out.append(val)
    return " | ".join(out)

# Include IfcRelSpaceBoundary description/name etc

def relspace_text(space):
    out = []
    for rel in getattr(space, "BoundedBy", []) or []:
        if not rel:
            continue
        for attr in ["Name", "Description"]:
            v = getattr(rel, attr, None)
            if isinstance(v, str) and v:
                out.append(v)
        # related building element
        be = getattr(rel, "RelatedBuildingElement", None)
        if be:
            for attr in ["Name", "Description", "ObjectType"]:
                v = getattr(be, attr, None)
                if isinstance(v, str) and v:
                    out.append(v)
            out.append(pset_text(be))
    return " | ".join([s for s in out if s])

