# Find wall that is geometrically limited when it extends along its alignment.
# Interpreted as: wall has an IfcAxis2/Alignment representation (axis curve), and its body length is shorter than the axis length (trimmed/limited extent).

from math import sqrt


def dist(p,q):
    return sqrt((p[0]-q[0])**2 + (p[1]-q[1])**2 + (p[2]-q[2])**2)


def polyline_length(pl):
    pts = [tuple(map(float, p.Coordinates)) for p in pl.Points]
    if len(pts) < 2:
        return 0.0
    return sum(dist(pts[i], pts[i+1]) for i in range(len(pts)-1))


def curve_length(curve):
    if not curve:
        return None
    t = curve.is_a()
    if t == 'IfcPolyline':
        return polyline_length(curve)
    # Handle trimmed curve around a polyline/line in a basic way
    if t == 'IfcTrimmedCurve':
        # try use BasisCurve
        base = curve.BasisCurve
        bl = curve_length(base)
        # If trims exist and are parametric, we cannot robustly compute without geometry.
        # Return base length as approximation.
        return bl
    if t == 'IfcCompositeCurve':
        total = 0.0
        for seg in curve.Segments or []:
            parent = seg.ParentCurve
            seglen = curve_length(parent)
            if seglen is None:
                return None
            total += seglen
        return total
    if t == 'IfcLine':
        # infinite; can't
        return None
    return None


def axis_curve_from_wall(wall):
    rep = wall.Representation
    if not rep:
        return None
    for r in rep.Representations or []:
        # Common identifiers: 'Axis', 'FootPrint', 'Body'
        if (r.RepresentationIdentifier or '').lower() == 'axis':
            items = r.Items or []
            if items:
                # could be IfcPolyline, IfcTrimmedCurve, IfcCompositeCurve, IfcShapeRepresentation items
                return items[0]
    return None


def body_curve_from_wall(wall):
    rep = wall.Representation
    if not rep:
        return None
    for r in rep.Representations or []:
        if (r.RepresentationIdentifier or '').lower() in ('body','footprint'):
            for it in r.Items or []:
                # IfcExtrudedAreaSolid -> SweptArea could be IfcRectangleProfileDef etc.
                # IfcSweptDiskSolid -> Directrix is curve
                # IfcSectionedSolidHorizontal -> Directrix
                if it.is_a('IfcSweptDiskSolid'):
                    return it.Directrix
                if it.is_a('IfcSweptDiskSolidPolygonal'):
                    return it.Directrix
                if it.is_a('IfcSectionedSolidHorizontal'):
                    return it.Directrix
                if it.is_a('IfcExtrudedAreaSolid'):
                    # no directrix; skip
                    continue
            # if representation is a curve (e.g., footprint)
            items = r.Items or []
            if items and items[0].is_a() in ('IfcPolyline','IfcCompositeCurve','IfcTrimmedCurve'):
                return items[0]
    return None


walls = []
for t in ('IfcWall','IfcWallStandardCase'):
    walls.extend(ifc.by_type(t))

candidates = []
for w in walls:
    axis = axis_curve_from_wall(w)
    if not axis:
        continue
    axis_len = curve_length(axis)
    if axis_len is None or axis_len == 0:
        continue
    body_curve = body_curve_from_wall(w)
    body_len = curve_length(body_curve) if body_curve else None
    # if we can compute body_len and it's significantly shorter than axis_len -> geometrically limited along alignment
    if body_len is not None and body_len > 0 and body_len < axis_len * 0.98:
        candidates.append((w.GlobalId, axis_len, body_len, w))

# If none found via body directrix, use another heuristic:
# Look for walls with IfcMaterialLayerSetUsage direction and explicit OverallWidth/Height? Not helpful.
# Fallback: if axis is composite and body is missing, pick wall with axis and has property set indicating 'Extent' or 'Length' smaller.
if not candidates:
    for w in walls:
        axis = axis_curve_from_wall(w)
        if not axis:
            continue
        axis_len = curve_length(axis)
        if axis_len is None or axis_len == 0:
            continue
        # try get nominal length from quantities
        nominal = None
        for rel in (w.IsDefinedBy or []):
            if rel.is_a('IfcRelDefinesByProperties'):
                ps = rel.RelatingPropertyDefinition
                if ps and ps.is_a('IfcElementQuantity'):
                    for q in ps.Quantities or []:
                        if q.is_a('IfcQuantityLength') and (q.Name or '').lower() in ('length','netlength','grosslength'):
                            nominal = float(q.LengthValue)
                            break
                if nominal is not None:
                    break
        if nominal is not None and nominal < axis_len * 0.98:
            candidates.append((w.GlobalId, axis_len, nominal, w))

# choose best candidate with maximum relative difference
best = None
for gid, a, b, w in candidates:
    diff = (a - b) / a if a else 0
    if best is None or diff > best[0]:
        best = (diff, gid, a, b)

result = best[1] if best else (candidates[0][0] if candidates else None)

