# helper: get boundaries of a space

def get_boundaries(space):
    # IFC2x3: BoundedBy inverse; IFC4: BoundedBy as well
    b = []
    try:
        b = list(getattr(space, 'BoundedBy') or [])
    except Exception:
        b = []
    return b


def boundary_has_door(sb):
    # IfcRelSpaceBoundary has RelatedBuildingElement (wall/door/window) and may reference an opening.
    el = None
    try:
        el = sb.RelatedBuildingElement
    except Exception:
        el = None
    if el and el.is_a('IfcDoor'):
        return True
    # sometimes boundary relates to wall but has connection geometry to opening; try RelatedBuildingElement of ParentBoundary etc.
    try:
        # check if boundary is to an opening element
        if hasattr(sb, 'RelatedBuildingElement') and sb.RelatedBuildingElement and sb.RelatedBuildingElement.is_a('IfcOpeningElement'):
            # try to find the filling element (door)
            opening = sb.RelatedBuildingElement
            for rel in ifc.get_inverse(opening):
                if rel.is_a('IfcRelFillsElement') and rel.RelatingOpeningElement == opening:
                    fe = rel.RelatedBuildingElement
                    if fe and fe.is_a('IfcDoor'):
                        return True
    except Exception:
        pass
    return False


def space_area(space):
    # try BaseQuantities with IfcQuantityArea named 'GrossFloorArea' or 'NetFloorArea'
    for rel in ifc.get_inverse(space):
        if rel.is_a('IfcRelDefinesByProperties'):
            ps = rel.RelatingPropertyDefinition
            if ps and ps.is_a('IfcElementQuantity') and ps.Quantities:
                for q in ps.Quantities:
                    if q.is_a('IfcQuantityArea'):
                        if (q.Name or '').lower() in ('grossfloorarea','netfloorarea','floorarea','area'):
                            try:
                                return float(q.AreaValue)
                            except Exception:
