    # fallback: look for Pset_SpaceCommon Area
    for rel in ifc.get_inverse(space):
        if rel.is_a('IfcRelDefinesByProperties'):
            pd = rel.RelatingPropertyDefinition
            if pd and pd.is_a('IfcPropertySet') and (pd.Name or '').lower() in ('pset_spacecommon','spacecommon'):
                for p in pd.HasProperties or []:
                    if p.is_a('IfcPropertySingleValue') and (p.Name or '').lower() == 'area':
                        try:
                            return float(p.NominalValue.wrappedValue)
                        except Exception:
