# Helper geometry functions (2D)
def poly_bbox(poly):
    xs=[p[0] for p in poly]; ys=[p[1] for p in poly]
    return (min(xs),min(ys),max(xs),max(ys))

def bbox_intersects(a,b,eps=1e-6):
    return not (a[2] < b[0]-eps or b[2] < a[0]-eps or a[3] < b[1]-eps or b[3] < a[1]-eps)

def point_in_poly(pt, poly):
    # ray casting
    x,y=pt
    inside=False
    n=len(poly)
    for i in range(n):
        x1,y1=poly[i]
        x2,y2=poly[(i+1)%n]
        if ((y1>y) != (y2>y)):
            xinters = (x2-x1)*(y-y1)/(y2-y1+1e-18)+x1
            if x < xinters:
                inside = not inside
    return inside

def dist2(a,b):
    return (a[0]-b[0])**2+(a[1]-b[1])**2

def door_centroid_from_placement(obj):
    # approximate door position from ObjectPlacement
    pl = getattr(obj,'ObjectPlacement',None)
    if not pl: return None
    # resolve IfcLocalPlacement chain
    x=y=0.0
    cur=pl
    # accumulate translations only
    steps=0
    while cur and steps<20:
        steps+=1
        rp = getattr(cur,'RelativePlacement',None)
        if rp and rp.is_a('IfcAxis2Placement3D'):
            loc = rp.Location
            if loc:
                coords = loc.Coordinates
                if coords and len(coords)>=2:
                    x += float(coords[0]); y += float(coords[1])
        elif rp and rp.is_a('IfcAxis2Placement2D'):
            loc = rp.Location
            if loc:
                coords = loc.Coordinates
                if coords and len(coords)>=2:
                    x += float(coords[0]); y += float(coords[1])
        cur = getattr(cur,'PlacementRelTo',None)
    return (x,y)

def get_space_outer_poly(space):
    rep = getattr(space,'Representation',None)
    if not rep: return None
    reps = rep.Representations or []
    for r in reps:
        items = getattr(r,'Items',None) or []
        for it in items:
            # We try: IfcExtrudedAreaSolid with IfcArbitraryClosedProfileDef
            if it.is_a('IfcExtrudedAreaSolid'):
                prof = it.SweptArea
                if prof and prof.is_a('IfcArbitraryClosedProfileDef'):
                    crv = prof.OuterCurve
                    if crv and crv.is_a('IfcPolyline'):
                        pts=[]
                        for p in crv.Points:
                            c=p.Coordinates
                            pts.append((float(c[0]),float(c[1])))
                        # drop duplicate last point if equals first
                        if len(pts)>2 and dist2(pts[0],pts[-1])<1e-12:
                            pts=pts[:-1]
                        return pts
            # IfcFacetedBrep etc not handled
    return None

