            loc=getattr(rp,'Location',None)
            if loc:
                c=loc.Coordinates
                if c and len(c)>=2:
                    x+=float(c[0]); y+=float(c[1])
        cur=getattr(cur,'PlacementRelTo',None)
    return (x,y)

def get_space_poly(space):
    rep=getattr(space,'Representation',None)
    if not rep: return None
    for r in rep.Representations or []:
        for it in getattr(r,'Items',None) or []:
            if it.is_a('IfcExtrudedAreaSolid'):
                prof=it.SweptArea
                if prof and prof.is_a('IfcArbitraryClosedProfileDef'):
                    crv=prof.OuterCurve
                    if crv and crv.is_a('IfcPolyline'):
                        pts=[(float(p.Coordinates[0]),float(p.Coordinates[1])) for p in crv.Points]
                        if len(pts)>2 and (pts[0][0]-pts[-1][0])**2+(pts[0][1]-pts[-1][1])**2<1e-12:
                            pts=pts[:-1]
                        return pts
    return None

def point_in_poly(pt, poly):
    x,y=pt
    inside=False
    n=len(poly)
    for i in range(n):
        x1,y1=poly[i]; x2,y2=poly[(i+1)%n]
        if (y1>y)!=(y2>y):
            xinters=(x2-x1)*(y-y1)/(y2-y1+1e-18)+x1
            if x<xinters:
                inside=not inside
    return inside

def poly_world(space):
    poly=get_space_poly(space)
    if not poly: return None
    tx,ty=placement_xy(space)
    return [(x+tx,y+ty) for x,y in poly]

def bbox(poly):
    xs=[p[0] for p in poly]; ys=[p[1] for p in poly]
    return (min(xs),min(ys),max(xs),max(ys))

def bbox_intersects(a,b,eps=1e-6):
    return not (a[2] < b[0]-eps or b[2] < a[0]-eps or a[3] < b[1]-eps or b[3] < a[1]-eps)

space_poly={}
space_bbox={}
for gid,sp in spaces.items():
    pw=poly_world(sp)
    if pw:
        space_poly[gid]=pw
        space_bbox[gid]=bbox(pw)

# door -> opening(s)
fills = defaultdict(list)
for rel in ifc.by_type('IfcRelFillsElement'):
    door = getattr(rel,'RelatedBuildingElement',None)
    op = getattr(rel,'RelatingOpeningElement',None)
    if door and op and door.is_a('IfcDoor'):
        fills[door.GlobalId].append(op)

# map door to spaces by door/opening placement proximity to spaces

door_to_spaces=defaultdict(set)
for dg,door in doors.items():
    px,py=placement_xy(door)
    ops=fills.get(dg)
    if ops:
        px,py=placement_xy(ops[0])
    d=1.0
    dbox=(px-d,py-d,px+d,py+d)
    candidates=[sg for sg,bb in space_bbox.items() if bbox_intersects(dbox,bb)]
    hits=[sg for sg in candidates if point_in_poly((px,py), space_poly[sg])]
    if len(hits)>=2:
        for sg in hits[:4]:
            door_to_spaces[dg].add(sg)
    else:
        if candidates:
            def ctrdist(sg):
                bb=space_bbox[sg]
                cx=(bb[0]+bb[2])/2; cy=(bb[1]+bb[3])/2
                return (cx-px)**2+(cy-py)**2
            for sg in sorted(candidates,key=ctrdist)[:2]:
                door_to_spaces[dg].add(sg)

adj=defaultdict(list)
for dg,sset in door_to_spaces.items():
    ss=list(sset)
    for i in range(len(ss)):
        for j in range(i+1,len(ss)):
            a=ss[i]; b=ss[j]
            if a!=b:
                adj[a].append((b,dg))
                adj[b].append((a,dg))

path_doors=[]
if start_gid in spaces and goal_gid in spaces:
    q=deque([start_gid])
    prev={start_gid:None}
    prev_door={}
    while q:
        cur=q.popleft()
        if cur==goal_gid: break
        for nb,dg in adj.get(cur,[]):
            if nb not in prev:
                prev[nb]=cur
                prev_door[nb]=dg
                q.append(nb)
    if goal_gid in prev:
        cur=goal_gid
        while prev[cur] is not None:
            path_doors.append(prev_door[cur])
            cur=prev[cur]
        path_doors=list(reversed(path_doors))

result={'doors_on_shortest_path': path_doors, 'num_doors_on_path': len(path_doors)}

import ifcopenshell

# Heuristic: identify the "radial hub" room as the space that is most connected via doors.
# Steps:
# 1) Collect IfcSpace entities (rooms).
# 2) Collect IfcDoor entities and map each door to the spaces it connects using IfcRelSpaceBoundary (preferred)
#    and, as fallback, IfcRelContainedInSpatialStructure (door contained in a space).
# 3) Build adjacency counts between spaces; pick space with highest degree.

spaces = [s for s in ifc.by_type('IfcSpace')]

# Map element -> set(spaces)
door_to_spaces = {}

# Preferred: use IfcRelSpaceBoundary (may be 2nd level boundaries too)
for rsb in ifc.by_type('IfcRelSpaceBoundary'):
    try:
        space = rsb.RelatingSpace
        elem = rsb.RelatedBuildingElement
    except Exception:
        continue
    if not space or not elem:
        continue
    if elem.is_a('IfcDoor'):
        door_to_spaces.setdefault(elem.id(), set()).add(space)

# Fallback: doors contained in a space (less reliable for connectivity)
# If a door has no rsb mapping, try containment
if any(True for _ in ifc.by_type('IfcRelContainedInSpatialStructure')):
    for rel in ifc.by_type('IfcRelContainedInSpatialStructure'):
        struct = rel.RelatingStructure
        if not struct or not struct.is_a('IfcSpace'):
            continue
        for elem in rel.RelatedElements or []:
            if elem and elem.is_a('IfcDoor'):
                door_to_spaces.setdefault(elem.id(), set()).add(struct)

# Build graph degree for spaces
space_degree = {s.id(): 0 for s in spaces}
space_neighbors = {s.id(): set() for s in spaces}

for door_id, sp_set in door_to_spaces.items():
    sp_list = list(sp_set)
    # consider connections between all spaces associated with the door
    if len(sp_list) >= 2:
        for i in range(len(sp_list)):
            for j in range(i+1, len(sp_list)):
                a = sp_list[i].id(); b = sp_list[j].id()
                if a in space_neighbors:
                    space_neighbors[a].add(b)
                if b in space_neighbors:
                    space_neighbors[b].add(a)

for sid, neigh in space_neighbors.items():
    space_degree[sid] = len(neigh)

# Choose best candidate
best_space = None
best_deg = -1
for s in spaces:
    deg = space_degree.get(s.id(), 0)
    if deg > best_deg:
        best_deg = deg
        best_space = s

# If no adjacency found, fallback to largest area/volume proxy via quantities
if best_space is None and spaces:
    best_space = spaces[0]

# Prepare result with some context
if best_space:
    result = {
        'global_id': best_space.GlobalId,
        'name': getattr(best_space, 'Name', None),
        'long_name': getattr(best_space, 'LongName', None),
        'degree': best_deg,
        'n_spaces': len(spaces),
        'n_doors_mapped': len(door_to_spaces)
    }
else:
    result = None

import ifcopenshell

# Find the "room inside a room" by detecting IfcSpace containment based on 2D/3D bounding boxes
# using IfcSpace.Representation. Prefer quantity/pset if available.

spaces = ifc.by_type('IfcSpace')

def get_space_placement_xyz(sp):
    # accumulate local placement translations
    loc = sp.ObjectPlacement
    x=y=z=0.0
    seen=0
    while loc and seen < 50:
        seen += 1
        try:
            rel = loc.RelativePlacement
        except Exception:
            rel = None
        if rel and hasattr(rel, 'Location') and rel.Location:
            c = rel.Location.Coordinates
            if c and len(c) >= 3:
                x += float(c[0]); y += float(c[1]); z += float(c[2])
            elif c and len(c) == 2:
                x += float(c[0]); y += float(c[1])
        try:
            loc = loc.PlacementRelTo
        except Exception:
            loc = None
    return (x,y,z)

def get_bbox_from_representation(sp):
    rep = sp.Representation
    if not rep:
        return None
    # Traverse items; handle SweptSolid (IfcExtrudedAreaSolid) and FacetedBrep minimally.
    minx=miny=minz=1e18
    maxx=maxy=maxz=-1e18
    found=False

    # helper to update bounds
    def upd(x,y,z):
        nonlocal minx,miny,minz,maxx,maxy,maxz,found
        found=True
        minx=min(minx,x); miny=min(miny,y); minz=min(minz,z)
        maxx=max(maxx,x); maxy=max(maxy,y); maxz=max(maxz,z)

    def process_curve(curve, zval=0.0):
        # Return list of 2D points
        pts=[]
        if not curve:
            return pts
        t = curve.is_a()
        if t == 'IfcPolyline':
            for p in curve.Points:
                c=p.Coordinates
                if len(c)>=2:
                    pts.append((float(c[0]), float(c[1])))
        elif t == 'IfcCompositeCurve':
            for seg in curve.Segments:
                pts += process_curve(seg.ParentCurve, zval)
        return pts

    def process_profile(profile):
        pts=[]
        if not profile:
            return pts
        t=profile.is_a()
        if t in ('IfcArbitraryClosedProfileDef','IfcArbitraryProfileDefWithVoids'):
            pts += process_curve(profile.OuterCurve)
        elif t == 'IfcRectangleProfileDef':
            x = float(profile.XDim); y=float(profile.YDim)
            pts += [(-x/2,-y/2),(x/2,-y/2),(x/2,y/2),(-x/2,y/2)]
        elif t == 'IfcCircleProfileDef':
            r=float(profile.Radius)
            # approximate bbox
            pts += [(-r,-r),(r,r)]
        return pts

    def process_item(item):
        nonlocal minx,miny,minz,maxx,maxy,maxz,found
        if not item:
            return
        it = item.is_a()
        if it == 'IfcExtrudedAreaSolid':
            # profile in local coordinates; extruded along direction with depth
            prof_pts = process_profile(item.SweptArea)
            depth = float(item.Depth) if item.Depth is not None else 0.0
            # position
            pos = item.Position
            ox=oy=oz=0.0
            if pos and pos.Location and pos.Location.Coordinates:
                c=pos.Location.Coordinates
                if len(c)>=3:
                    ox,oy,oz = float(c[0]),float(c[1]),float(c[2])
                elif len(c)==2:
                    ox,oy = float(c[0]),float(c[1])
            # update bbox for profile at z=0 and z=depth (assuming extrusion along +Z in local)
            if prof_pts:
                xs=[p[0] for p in prof_pts]; ys=[p[1] for p in prof_pts]
                mnx,mxx=min(xs),max(xs)
                mny,mxy=min(ys),max(ys)
                upd(ox+mnx, oy+mny, oz)
                upd(ox+mxx, oy+mxy, oz+depth)
        elif it == 'IfcFacetedBrep':
            # iterate vertices
            try:
                outer = item.Outer
                for face in outer.CfsFaces:
                    for bound in face.Bounds:
                        loop = bound.Bound
                        if loop.is_a('IfcPolyLoop'):
                            for p in loop.Polygon:
                                c=p.Coordinates
                                if len(c)>=3:
                                    upd(float(c[0]),float(c[1]),float(c[2]))
                                elif len(c)==2:
                                    upd(float(c[0]),float(c[1]),0.0)
            except Exception:
                pass
        elif it == 'IfcMappedItem':
            # process source representation items (ignoring transforms)
            try:
                src = item.MappingSource
                if src and src.MappedRepresentation:
                    for it2 in src.MappedRepresentation.Items:
                        process_item(it2)
            except Exception:
                pass
        elif it == 'IfcBooleanClippingResult' or it == 'IfcBooleanResult':
            # process first operand
            try:
                process_item(item.FirstOperand)
            except Exception:
                pass
        # else: ignore

    # iterate representations
    for r in rep.Representations:
        try:
            for item in r.Items:
                process_item(item)
        except Exception:
            pass

    if not found:
        return None

    # add object placement offset
    px,py,pz = get_space_placement_xyz(sp)
    return (minx+px, miny+py, minz+pz, maxx+px, maxy+py, maxz+pz)

bboxes={}
for sp in spaces:
    bb = get_bbox_from_representation(sp)
    if bb:
        bboxes[sp.GlobalId]=bb

# containment test
# A inside B if bbox A fully within bbox B with small tolerance and A not equal B.

tol=1e-6
inside_pairs=[]
ids=list(bboxes.keys())
for i in range(len(ids)):
    ida=ids[i]; a=bboxes[ida]
    for j in range(len(ids)):
        if i==j: continue
        idb=ids[j]; b=bboxes[idb]
        if (a[0] >= b[0]-tol and a[1] >= b[1]-tol and a[2] >= b[2]-tol and
            a[3] <= b[3]+tol and a[4] <= b[4]+tol and a[5] <= b[5]+tol):
            # ensure strict inside (not just equal)
            if (a[0] > b[0]+tol or a[1] > b[1]+tol or a[2] > b[2]+tol or
                a[3] < b[3]-tol or a[4] < b[4]-tol or a[5] < b[5]-tol):
                inside_pairs.append((ida,idb))

# Determine the "room inside a room" as the inner space of any containment.
# If multiple, pick the one with smallest volume (most nested).

def vol(bb):
    return max(0.0,(bb[3]-bb[0]))*max(0.0,(bb[4]-bb[1]))*max(0.0,(bb[5]-bb[2]))

inner_ids=set([p[0] for p in inside_pairs])
if not inner_ids:
    result = None
else:
    # pick minimal volume among inner ids
    inner_list=sorted(list(inner_ids), key=lambda gid: vol(bboxes[gid]))
    result = inner_list[0]

