# Goal: Provide the GlobalId of the room perceived as a semi-public-space.
# Heuristic approach (no geometry):
# - Collect spaces (IfcSpace). If none, fall back to IfcZone or IfcSpatialStructureElement names.
# - Prefer spaces whose Name/LongName/Description/ObjectType/Pset labels indicate semi-public.
# - Keywords: lobby, foyer, reception, corridor, hallway, circulation, atrium, waiting, lounge, common, shared.
# - Exclude strongly public (entrance hall?) vs private (office, bedroom, wc, storage) with negative keywords.

import re

spaces = list(ifc.by_type('IfcSpace'))

def norm(s):
    return (s or '').strip().lower()

def get_texts(sp):
    texts = []
    for attr in ['Name','LongName','Description','ObjectType']:
        if hasattr(sp, attr):
            v = getattr(sp, attr)
            if v:
                texts.append(str(v))
    # gather psets
    try:
        for rel in getattr(sp, 'IsDefinedBy', []) or []:
            if rel.is_a('IfcRelDefinesByProperties'):
                pdef = rel.RelatingPropertyDefinition
                if pdef and pdef.is_a('IfcPropertySet'):
                    # include pset name
                    if pdef.Name:
                        texts.append(str(pdef.Name))
                    for prop in pdef.HasProperties or []:
                        if prop.is_a('IfcPropertySingleValue'):
                            pname = prop.Name
                            val = prop.NominalValue.wrappedValue if prop.NominalValue else None
                            if pname:
                                texts.append(str(pname))
                            if val is not None:
                                texts.append(str(val))
    except Exception:
        pass
    return [t for t in texts if t]

pos_kw = {
    'semi-public': 8,
