def score_space(sp):
    texts = get_texts(sp)
    blob = ' | '.join(texts)
    b = norm(blob)
    score = 0
    # direct keyword scores
    for k,w in pos_kw.items():
        if k in b:
            score += w
    for k,w in neg_kw.items():
        if k in b:
            score -= w
    # if explicitly public vs semi-public
    if 'public' in b and ('semi' not in b and 'semi-' not in b and 'semi ' not in b):
        score -= 1  # slightly penalize fully public
    # prefer circulation-type spaces when semi-public not explicit
    # but avoid stair/elevator shafts
    if 'stair' in b or 'staircase' in b:
        score -= 3
    if 'elevator' in b or 'lift' in b:
        score -= 3
    return score, blob

cands = []
