        # element props
        for pset, pname, pval in get_pset_kv(el):
            blob = ' '.join([pset,pname,pval, el.is_a(), el.Name or ''])
            if any_indirect(blob):
                score += 100
    # tie-break
    if score > best_score or (score == best_score and has_light and not best_has_light):
        best = sp
        best_score = score
        best_has_light = has_light

result = best.GlobalId if best and best_score>0 else None

