# Direct search for any property/attribute containing 'indirect' and resolve to containing IfcSpace.

import re

def collect_strings(ent):
    strs = []
    for attr in ['Name','LongName','Description','ObjectType','Tag','PredefinedType']:
        if hasattr(ent, attr):
            v = getattr(ent, attr)
            if v:
                strs.append(str(v))
    # psets
    for rel in getattr(ent, 'IsDefinedBy', []) or []:
        if rel.is_a('IfcRelDefinesByProperties'):
            pdef = rel.RelatingPropertyDefinition
            if pdef and pdef.is_a('IfcPropertySet'):
                strs.append(str(pdef.Name or ''))
                for prop in pdef.HasProperties or []:
                    if not prop:
                        continue
                    strs.append(str(prop.Name or ''))
                    if prop.is_a('IfcPropertySingleValue'):
                        val = prop.NominalValue
                        if val is not None:
                            try:
                                strs.append(str(val.wrappedValue))
                            except Exception:
                                strs.append(str(val))
    return [s for s in strs if s]

def has_indirect(ent):
    t = ' '.join(collect_strings(ent)).lower()
    return 'indirect' in t or 'indirekt' in t

# map product id -> containing space
prod_to_space = {}
for rel in ifc.by_type('IfcRelContainedInSpatialStructure'):
    st = rel.RelatingStructure
    if st and st.is_a('IfcSpace'):
        for el in rel.RelatedElements or []:
            prod_to_space[el.id()] = st

hits = []
for ent in ifc.by_type('IfcRoot'):
    if has_indirect(ent):
        # if it's a space, keep; else resolve containment
        if ent.is_a('IfcSpace'):
            hits.append(ent)
        else:
            sp = prod_to_space.get(ent.id())
            if sp:
                hits.append(sp)

# unique
uniq = {}
for sp in hits:
    uniq[sp.GlobalId] = sp

# if multiple, choose by smallest GlobalId (stable)
result = sorted(uniq.keys())[0] if uniq else None

# Purpose: identify wall intended to receive a vertical light gradient.
# Heuristic: search for walls with names/descriptions/materials/props mentioning gradient/light/uplight/downlight/washer.
# If none, fall back to wall with largest single face vertical extent? (avoid geom). We'll primarily use semantic metadata.

import re

keywords = [
    r"gradient", r"light\s*gradient", r"vertical\s*gradient",
    r"wash(er|ing)?", r"wall\s*wash", r"uplight", r"downlight",
    r"graz(e|ing)", r"illuminat(ed|ion)", r"backlight", r"lighting",
    r"ombre", r"fade",
]
kw_re = re.compile("|".join(keywords), re.IGNORECASE)

walls = ifc.by_type("IfcWall") + ifc.by_type("IfcWallStandardCase")

def get_pset_props(elem):
    out = []
    # IsDefinedBy relationships
    for rel in getattr(elem, "IsDefinedBy", []) or []:
        if not rel or not rel.is_a("IfcRelDefinesByProperties"):
            continue
        pdef = rel.RelatingPropertyDefinition
        if not pdef:
            continue
        if pdef.is_a("IfcPropertySet"):
            for prop in pdef.HasProperties or []:
                if prop.is_a("IfcPropertySingleValue"):
                    name = prop.Name or ""
                    val = ""
                    try:
                        if prop.NominalValue is not None:
                            val = str(prop.NominalValue.wrappedValue)
                    except Exception:
                        try:
                            val = str(prop.NominalValue)
                        except Exception:
                            val = ""
                    out.append((pdef.Name or "", name, val))
                else:
                    out.append((pdef.Name or "", prop.Name or "", ""))
        else:
            # other property definitions (e.g., quantity sets)
            n = getattr(pdef, "Name", "") or ""
            out.append((n, "", ""))
    return out


def get_material_names(elem):
    names = []
    for rel in getattr(elem, "HasAssociations", []) or []:
        if rel and rel.is_a("IfcRelAssociatesMaterial"):
            mat = rel.RelatingMaterial
            if not mat:
                continue
            # handle different material structures
            def handle(m):
                if not m:
                    return
                if hasattr(m, "Name") and m.Name:
                    names.append(m.Name)
                if m.is_a("IfcMaterialLayerSetUsage"):
                    handle(m.ForLayerSet)
                if m.is_a("IfcMaterialLayerSet"):
                    for layer in m.MaterialLayers or []:
                        handle(layer.Material)
                if m.is_a("IfcMaterialConstituentSet"):
                    for c in m.MaterialConstituents or []:
                        handle(c.Material)
                if m.is_a("IfcMaterialProfileSetUsage"):
                    handle(m.ForProfileSet)
                if m.is_a("IfcMaterialProfileSet"):
                    for p in m.MaterialProfiles or []:
                        handle(p.Material)
                if m.is_a("IfcMaterialList"):
                    for mm in m.Materials or []:
                        handle(mm)
            handle(mat)
    # unique keep order
    seen=set(); uniq=[]
    for n in names:
        if n not in seen:
            seen.add(n); uniq.append(n)
    return uniq

candidates = []
for w in walls:
    text_bits = []
    for attr in ["Name", "Description", "ObjectType", "Tag"]:
        v = getattr(w, attr, None)
        if v:
            text_bits.append(str(v))
    # psets
    pprops = get_pset_props(w)
    for psn, pn, pv in pprops:
        if psn: text_bits.append(psn)
        if pn: text_bits.append(pn)
        if pv: text_bits.append(pv)
    # materials
    mats = get_material_names(w)
    text_bits += mats

    blob = "\n".join(text_bits)
    hits = kw_re.findall(blob)
    score = 0
    if hits:
        score += 10*len(hits)
    # boost if 'gradient' explicitly
    if re.search(r"gradient", blob, re.IGNORECASE):
        score += 50
    if re.search(r"vertical", blob, re.IGNORECASE) and re.search(r"gradient", blob, re.IGNORECASE):
        score += 50
    if re.search(r"wall\s*wash|washer", blob, re.IGNORECASE):
        score += 20

    if score>0:
        candidates.append({
            "gid": w.GlobalId,
            "name": getattr(w, "Name", None),
            "score": score,
            "preview": blob[:500]
        })

# If no semantic candidates, choose a likely 'feature wall': by pset indicating finish/feature/accent.
if not candidates:
    feature_re = re.compile(r"feature|accent|statement|art|gallery|display|wash|light", re.IGNORECASE)
    for w in walls:
        blob = "\n".join([str(getattr(w,a,None) or "") for a in ["Name","Description","ObjectType","Tag"]])
        pprops = get_pset_props(w)
        for psn,pn,pv in pprops:
            blob += "\n"+" ".join([psn,pn,pv])
        score = 0
        if feature_re.search(blob):
            score = 1
        if score:
            candidates.append({"gid": w.GlobalId, "name": getattr(w,"Name",None), "score": score, "preview": blob[:500]})

# Pick best scored; tie-break by having name/description
best = None
if candidates:
    candidates.sort(key=lambda c: (c["score"], 1 if c.get("name") else 0), reverse=True)
    best = candidates[0]

result = {
    "selected_global_id": best["gid"] if best else None,
    "selected_name": best.get("name") if best else None,
    "candidate_count": len(candidates),
    "top_candidates": candidates[:5],
}

# Fallback approach without geometry: infer the likely 'intentionally designed' wall by
# (1) being exposed (external or internal finish) and
# (2) having the largest net wall area from base quantities.
# Many authoring tools populate Qto_WallBaseQuantities with NetSideArea/GrossSideArea.

walls = ifc.by_type('IfcWall') + ifc.by_type('IfcWallStandardCase')

def wall_quantities(w):
    q = {}
    for rel in getattr(w, 'IsDefinedBy', []) or []:
        if not rel or not rel.is_a('IfcRelDefinesByProperties'):
            continue
        pdef = rel.RelatingPropertyDefinition
        if not pdef or not pdef.is_a('IfcElementQuantity'):
            continue
        for qq in pdef.Quantities or []:
            if qq.is_a('IfcQuantityArea'):
                try:
                    q[qq.Name] = float(qq.AreaValue)
                except Exception:
                    pass
            elif qq.is_a('IfcQuantityLength'):
                try:
                    q[qq.Name] = float(qq.LengthValue)
                except Exception:
                    pass
    return q

best = None
for w in walls:
    q = wall_quantities(w)
    # prefer NetSideArea, then GrossSideArea, then GrossArea (rare)
    area = None
    for k in ['NetSideArea', 'GrossSideArea', 'NetArea', 'GrossArea', 'Area']:
        if k in q:
            area = q[k]
            break
    if area is None:
        continue
    # Heuristic boost if description/name suggests feature/finish wall
    text = ' '.join([str(getattr(w,a,'') or '') for a in ['Name','Description','ObjectType','Tag']])
    boost = 1.0
    low = text.lower()
    if any(s in low for s in ['feature','accent','gallery','display','light','wash','gradient']):
        boost = 1.2
    score = area * boost
    if best is None or score > best['score']:
        best = {'gid': w.GlobalId, 'name': getattr(w,'Name',None), 'area': area, 'score': score, 'text': text.strip(), 'q': q}

# If still none (no quantities), just pick first wall as last resort.
if best is None and walls:
    w = walls[0]
    best = {'gid': w.GlobalId, 'name': getattr(w,'Name',None), 'area': None, 'score': None, 'text': ' '.join([str(getattr(w,a,'') or '') for a in ['Name','Description','ObjectType','Tag']]).strip(), 'q': {}}

result = best

