# Helper to safely get string-ish attributes

def get_attr(e, name, default=None):
    try:
        v = getattr(e, name)
        return v if v not in (None, "") else default
    except Exception:
        return default

spaces = ifc.by_type("IfcSpace")

support_keywords = {
    "support", "ancillary", "service", "serving", "secondary",
    "storage", "store", "janitor", "cleaner", "cleaning",
    "toilet", "wc", "bath", "shower", "restroom",
