    "closet", "cloak", "wardrobe",
    "stair", "stairs", "staircase", "lift", "elevator",
    "shaft", "risers", "riser",
}

main_keywords = {
    "office", "bedroom", "living", "classroom", "meeting", "conference",
    "lab", "laboratory", "shop", "retail", "storefront",
    "dining", "restaurant", "kitchen", "ward", "patient",
}

# Determine support/main classification using multiple hints.

def classify_space(sp):
    name = (get_attr(sp, "Name", "") or "").strip()
    longname = (get_attr(sp, "LongName", "") or "").strip()
    objtype = (get_attr(sp, "ObjectType", "") or "").strip()

    # PredefinedType may exist in IFC4; in IFC2x3 it's often absent
    pdt = None
    try:
        pdt = sp.PredefinedType
    except Exception:
        pdt = None

    text = " ".join([name, longname, objtype, str(pdt) if pdt else ""]).lower()

    # direct property hints
    is_support = False
    is_main = False

    # keyword scan
    for kw in support_keywords:
        if kw in text:
            is_support = True
            break
    for kw in main_keywords:
        if kw in text:
            is_main = True
            break

    # If explicitly marked as EXTERNAL or similar, ignore
    if pdt and str(pdt).upper() in ("EXTERNAL", "EXTERNALSPACE"):
        return "other"

    # Heuristic: spaces named like "Room" with number are probably main
    if not is_support:
        import re
        if re.search(r"\b(room|raum|chambre)\b", text) and re.search(r"\b\d+\b", text):
            is_main = True

    if is_support and not is_main:
        return "support"
    if is_main and not is_support:
        return "main"
    # ambiguous: prefer support if contains typical support tokens
    if is_support and is_main:
        return "support"
    return "other"

# Find corresponding main room for a support space.
# Use naming conventions like "<main> - <support>", "<main>_<support>", "<main>/<support>", etc.

def find_corresponding_main(support_sp, mains):
    import re
    name = (get_attr(support_sp, "Name", "") or "").strip()
    longname = (get_attr(support_sp, "LongName", "") or "").strip()
    candidates_text = [t for t in [name, longname] if t]
    if not candidates_text:
        return None

    # Build a quick lookup by lowercase name/longname
    main_by_token = {}
    for m in mains:
        for t in [(get_attr(m, "Name", "") or "").strip(), (get_attr(m, "LongName", "") or "").strip()]:
            if t:
                main_by_token.setdefault(t.lower(), []).append(m)

    # Try to extract a probable main label from support label using separators
    seps = ["-", "_", "/", "\\", ":", "|", ",", ";"]
    for txt in candidates_text:
        low = txt.lower()
        for sep in seps:
            if sep in low:
                left = low.split(sep)[0].strip()
                right = low.split(sep)[-1].strip()
                # Choose the part that looks less like support keyword
                def looks_support(part):
                    for kw in support_keywords:
                        if kw in part:
                            return True
                    return False
                parts = [p.strip() for p in low.split(sep) if p.strip()]
                # test each part as potential main label
                for p in parts:
                    if not looks_support(p) and p in main_by_token:
                        return main_by_token[p][0]
                # fallback: left if right looks support
                if looks_support(right) and left in main_by_token:
                    return main_by_token[left][0]

    # Try substring match: main name contained in support name
    for m in mains:
        mn = ((get_attr(m, "Name", "") or "") + " " + (get_attr(m, "LongName", "") or "")).lower().strip()
        if not mn:
            continue
        for txt in candidates_text:
            low = txt.lower()
            if mn and mn in low:
                return m

    # Try matching by room number: extract first number from support and find main with same number
    def first_number(s):
        import re
        m = re.search(r"(\d+[A-Za-z]?)", s)
        return m.group(1) if m else None

    sup_num = None
    for txt in candidates_text:
        sup_num = first_number(txt)
        if sup_num:
            break
    if sup_num:
        for m in mains:
            mt = " ".join([(get_attr(m, "Name", "") or ""), (get_attr(m, "LongName", "") or "")]).lower()
            if sup_num.lower() in mt:
                return m

    return None

mains = []
supports = []
for sp in spaces:
    cls = classify_space(sp)
    if cls == "main":
        mains.append(sp)
    elif cls == "support":
        supports.append(sp)

pairs = []
for s in supports:
    main = find_corresponding_main(s, mains)
    if main:
        pairs.append({
            "support_global_id": s.GlobalId,
            "main_global_id": main.GlobalId
        })

# Deduplicate support ids
seen = set()
dedup_pairs = []
for p in pairs:
    if p["support_global_id"] in seen:
        continue
    seen.add(p["support_global_id"])
    dedup_pairs.append(p)

result = {
    "support_rooms_global_ids": [p["support_global_id"] for p in dedup_pairs],
    "pairs": dedup_pairs,
    "counts": {
        "total_spaces": len(spaces),
        "classified_main": len(mains),
        "classified_support": len(supports),
        "paired_support": len(dedup_pairs),
    }
}

